    fn image_object_url(download_base: &str, object_key: &str) -> Result<String, RpcError> {
        let mut url = url::Url::parse(download_base).map_err(RpcError::internal)?;
        url.path_segments_mut()
            .map_err(|_| {
                RpcError::internal(anyhow::anyhow!(
                    "canonical image delivery URL cannot carry paths"
                ))
            })?
            .pop_if_empty()
            .extend(object_key.split('/'));
        Ok(url.to_string())
    }

    fn control_image_download_base(&self, registry_id: i64) -> Result<String, RpcError> {
        let mut url = url::Url::parse(&self.external_url).map_err(RpcError::internal)?;
        url.path_segments_mut()
            .map_err(|_| RpcError::internal(anyhow::anyhow!("Hub URL cannot carry paths")))?
            .pop_if_empty()
            .extend(["-", "images", &registry_id.to_string(), ""]);
        Ok(url.to_string())
    }

    fn system_image_message(
        &self,
        download_base: &str,
        image: crate::db::IndexedSystemImage,
        channel: Option<&str>,
        cache_urls: &[String],
        cache_delivery: bool,
    ) -> Result<pb::SystemImage, RpcError> {
        let delivery = image.delivery;
        let uki = delivery.uki.clone();
        let store_backed =
            delivery.is_store_backed() || (cache_delivery && !image.store_path.is_empty());
        Ok(pb::SystemImage {
            package: image.package,
            release: image.release,
            channel: channel.unwrap_or_default().to_string(),
            platform: image.platform,
            architecture: delivery.architecture,
            format: image.format,
            logical_image_id: delivery.logical_image_id,
            filename: delivery.filename,
            download_url: if store_backed {
                String::new()
            } else {
                Self::image_object_url(download_base, &delivery.object_key)?
            },
            media_type: delivery.media_type,
            compression: image_compression_name(delivery.compression).to_string(),
            byte_size: delivery.byte_size,
            sha256: delivery.sha256,
            compatible_targets: delivery
                .compatible_targets
                .into_iter()
                .map(image_target_name)
                .map(str::to_string)
                .collect(),
            boot_verification: image_verification_name(delivery.uki.verification).to_string(),
            object_key: delivery.object_key,
            image_info: Some(pb::ImageInfo {
                filename: delivery.image_info.filename,
                download_url: if store_backed {
                    String::new()
                } else {
                    Self::image_object_url(download_base, &delivery.image_info.object_key)?
                },
                object_key: delivery.image_info.object_key,
                media_type: delivery.image_info.media_type,
                byte_size: delivery.image_info.byte_size,
                sha256: delivery.image_info.sha256,
                store_path: delivery.image_info.store_path,
                nar_hash: delivery.image_info.nar_hash,
                nar_size: delivery.image_info.nar_size,
            }),
            logical_disk_sha256: delivery.logical_disk_sha256,
            rootfs_sha256: delivery.rootfs_sha256,
            uki: Some(pb::ImageUki {
                filename: uki.filename,
                esp_path: uki.esp_path,
                byte_size: uki.byte_size,
                sha256: uki.sha256,
                verification: image_verification_name(uki.verification).to_string(),
                signer_cert_sha256: uki.signer_cert_sha256.unwrap_or_default(),
                sbat: uki
                    .sbat
                    .into_iter()
                    .map(|entry| pb::SbatGeneration {
                        component: entry.component,
                        generation: entry.generation,
                    })
                    .collect(),
                measured: uki.measured,
                expected_pcr11: uki.expected_pcr11.unwrap_or_default(),
            }),
            release_verification: "verified".to_string(),
            store_path: store_backed.then_some(image.store_path).unwrap_or_default(),
            nar_hash: store_backed.then_some(image.nar_hash).unwrap_or_default(),
            nar_size: if store_backed { image.nar_size } else { 0 },
            cache_urls: cache_urls.to_vec(),
        })
    }

    /// `ImageService.ListImages` lists signed, directly downloadable disk encodings.
    ///
    /// # Errors
    ///
    /// Returns the normal registry visibility error, invalid selection errors,
    /// or an internal error when authenticated index metadata is malformed.
    pub async fn list_images(
        &self,
        auth: Option<&str>,
        req: pb::ListImagesRequest,
    ) -> Result<pb::ListImagesResponse, RpcError> {
        let registry = self.registry_or_not_found(&req.slug).await?;
        self.require_read(auth, &registry).await?;
        let control_base = self.control_image_download_base(registry.id)?;
        let download_base = if registry.visibility == "public" {
            self.registry_consumer_url(&registry)
                .await
                .unwrap_or(control_base)
        } else {
            control_base
        };
        if !req.release.is_empty() && !req.channel.is_empty() {
            return Err(RpcError::invalid(
                "release and channel are mutually exclusive",
            ));
        }
        let release = (!req.release.is_empty()).then(|| req.release.clone());
        let mut channel_releases = None;
        if !req.channel.is_empty() {
            let selected = self
                .db
                .list_channels(registry.id)
                .await
                .map_err(RpcError::internal)?
                .into_iter()
                .find(|candidate| candidate.name == req.channel)
                .ok_or_else(|| RpcError::not_found("channel"))?;
            let releases = selected
                .partitions
                .into_iter()
                .flatten()
                .collect::<HashSet<_>>();
            if releases.is_empty() {
                return Err(RpcError::FailedPrecondition(
                    "channel has no assigned release partitions".to_string(),
                ));
            }
            channel_releases = Some(releases);
        }
        let target = parse_image_target(&req.target)?;
        let cache_delivery = registry.visibility == "public";
        let cache_urls = if cache_delivery {
            self.db
                .registry_cache_stack_entries(registry.id)
                .await
                .map_err(RpcError::internal)?
                .into_iter()
                .map(|entry| entry.committed_url)
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let mut messages = Vec::new();
        for image in self
            .db
            .list_system_images(registry.id)
            .await
            .map_err(RpcError::internal)?
        {
            if release
                .as_ref()
                .is_some_and(|value| value != &image.release)
                || channel_releases
                    .as_ref()
                    .is_some_and(|releases| !releases.contains(&image.release))
                || (!req.package.is_empty() && req.package != image.package)
                || (!req.architecture.is_empty() && req.architecture != image.delivery.architecture)
                || (!req.format.is_empty() && req.format != image.format)
                || target.is_some_and(|value| !image.delivery.compatible_targets.contains(&value))
            {
                continue;
            }
            messages.push(self.system_image_message(
                &download_base,
                image,
                (!req.channel.is_empty()).then_some(req.channel.as_str()),
                &cache_urls,
                cache_delivery,
            )?);
        }
        let (images, next_page_token) = paginate(messages, req.page_size, &req.page_token)?;
        Ok(pb::ListImagesResponse {
            images,
            next_page_token,
        })
    }

    /// `ImageService.GetImage` inspects one exact immutable image encoding.
    ///
    /// # Errors
    ///
    /// Returns an invalid-argument error for an incomplete identity and a
    /// not-found or failed-precondition error unless exactly one image matches.
    pub async fn get_image(
        &self,
        auth: Option<&str>,
        req: pb::GetImageRequest,
    ) -> Result<pb::GetImageResponse, RpcError> {
        if req.release.is_empty() || req.architecture.is_empty() || req.format.is_empty() {
            return Err(RpcError::invalid(
                "release, architecture, and format are required",
            ));
        }
        self.resolve_image(
            auth,
            pb::ResolveImageRequest {
                slug: req.slug,
                release: req.release,
                channel: String::new(),
                architecture: req.architecture,
                format: req.format,
                target: String::new(),
                package: req.package,
            },
        )
        .await
    }

    /// `ImageService.ResolveImage` resolves a release or channel selection.
    ///
    /// # Errors
    ///
    /// Returns the normal registry visibility error, invalid selection errors,
    /// not found when no image matches, or failed precondition when ambiguous.
    pub async fn resolve_image(
        &self,
        auth: Option<&str>,
        req: pb::ResolveImageRequest,
    ) -> Result<pb::GetImageResponse, RpcError> {
        if req.release.is_empty() == req.channel.is_empty() {
            return Err(RpcError::invalid(
                "exactly one of release or channel is required",
            ));
        }
        let registry = self.registry_or_not_found(&req.slug).await?;
        self.require_read(auth, &registry).await?;
        let channel_label = (!req.channel.is_empty()).then(|| req.channel.clone());
        let mut release = req.release;
        if let Some(channel) = channel_label.as_deref() {
            release = self
                .db
                .list_channels(registry.id)
                .await
                .map_err(RpcError::internal)?
                .into_iter()
                .find(|candidate| candidate.name == channel)
                .ok_or_else(|| RpcError::not_found("channel"))?
                .frontier
                .ok_or_else(|| {
                    RpcError::FailedPrecondition("channel has no release frontier".to_string())
                })?;
        }
        let mut response = self
            .list_images(
                auth,
                pb::ListImagesRequest {
                    slug: req.slug,
                    release,
                    channel: String::new(),
                    architecture: req.architecture,
                    format: req.format,
                    target: req.target,
                    page_size: 2,
                    page_token: String::new(),
                    package: req.package,
                },
            )
            .await?;
        if let Some(channel) = channel_label {
            for image in &mut response.images {
                image.channel = channel.clone();
            }
        }
        match response.images.as_slice() {
            [image] => Ok(pb::GetImageResponse {
                image: Some(image.clone()),
            }),
            [] => Err(RpcError::not_found("system image")),
            _ => Err(RpcError::FailedPrecondition(
                "image selection is ambiguous; specify architecture, format, or target".to_string(),
            )),
        }
    }

    /// Resolve an org by slug or map a miss to `NotFound`.
    async fn org_or_not_found(&self, slug: &str) -> Result<crate::db::OrgRecord, RpcError> {
        self.db
            .org_by_slug(slug)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("org"))
    }

    /// `OrganizationService.GetOrganization` — looks up an organization by slug.
    ///
    /// # Errors
    ///
    /// Returns [`RpcError::NotFound`] for an unknown slug and
    /// [`RpcError::Internal`] on database failure.
    pub async fn get_organization(
        &self,
        _auth: Option<&str>,
        req: pb::GetOrganizationRequest,
    ) -> Result<pb::OrganizationResponse, RpcError> {
        let org = self.org_or_not_found(&req.slug).await?;
        Ok(pb::OrganizationResponse {
            organization: Some(organization_message(&org)),
        })
    }

    /// `OrganizationService.ListOrganizations` — the caller's organizations,
    /// ordered by slug.
    ///
    /// This is *not* a public directory: the caller must present a bearer JWT,
    /// and each org is included only when that caller holds
    /// [`Permission::Read`] covering its scope (soft-deleted orgs are already
    /// excluded by [`Database::list_orgs`](crate::db::Database::list_orgs)).
    ///
    /// # Errors
    ///
    /// Returns [`RpcError::Unauthenticated`] for a missing/invalid bearer JWT,
    /// [`RpcError::InvalidArgument`] for a malformed `page_token`, and
    /// [`RpcError::Internal`] on database failure.
    pub async fn list_organizations(
        &self,
        auth: Option<&str>,
        req: pb::ListOrganizationsRequest,
    ) -> Result<pb::ListOrganizationsResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let all_orgs = self.db.list_orgs().await.map_err(RpcError::internal)?;
        let mut organizations: Vec<pb::Organization> = Vec::new();
        for org in all_orgs.iter() {
            if self
                .claims_allow(
                    Some(&claims),
                    Permission::Read,
                    &Scope::parse(&org.stable_id),
                )
                .await
            {
                organizations.push(organization_message(org));
            }
        }
        let (organizations, next_page_token) =
            paginate(organizations, req.page_size, &req.page_token)?;
        Ok(pb::ListOrganizationsResponse {
            organizations,
            next_page_token,
        })
    }

    /// Plans an organization profile update under an exact resource version.
    ///
    /// # Errors
    ///
    /// Returns an authentication, authorization, validation, stale-version, or
    /// persistence error.
    pub async fn plan_update_organization(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanUpdateOrganizationRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let org = self.org_or_not_found(&req.slug).await?;
        self.require_permission(
            &claims,
            Permission::MembersManage,
            &Scope::parse(&org.stable_id),
        )
        .await?;
        req.display_name = req.display_name.trim().to_string();
        if req.display_name.is_empty() || req.expected_resource_version.is_empty() {
            return Err(RpcError::invalid(
                "displayName and expectedResourceVersion are required",
            ));
        }
        if parse_resource_version(&req.expected_resource_version, org.resource_version)?
            != org.resource_version
        {
            return Err(RpcError::FailedPrecondition(
                "organization resource version is stale".to_string(),
            ));
        }
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let input = OrganizationUpdatePlanInput {
            request: req,
            org_id: org.id,
            baseline_resource_version: org.resource_version,
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            "update_organization",
            &org.stable_id,
            &input,
            &idempotency_key,
            vec![format!("update organization '{}' profile", org.slug)],
            Vec::new(),
            Some(confirmation_hash),
        )
        .await
    }

    /// Applies an organization profile update exactly once.
    ///
    /// # Errors
    ///
    /// Returns an authentication, confirmation, authorization, stale-plan, or
    /// persistence error.
    pub async fn apply_update_organization(
        &self,
        auth: Option<&str>,
        req: pb::ApplyOrganizationMutationRequest,
    ) -> Result<pb::OrganizationResponse, RpcError> {
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                "update_organization",
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            "update_organization",
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, OrganizationUpdatePlanInput) = self
            .load_control_plan(
                auth,
                &req.plan_id,
                "update_organization",
                Some(&req.confirmation_hash),
            )
            .await?;
        let mut org = self.org_or_not_found(&input.request.slug).await?;
        let claims = self.require_claims(auth)?;
        self.require_permission(
            &claims,
            Permission::MembersManage,
            &Scope::parse(&org.stable_id),
        )
        .await?;
        if org.id != input.org_id {
            return Err(RpcError::FailedPrecondition(
                "organization identity changed after planning".to_string(),
            ));
        }
        let exact_recovery = org.resource_version == input.baseline_resource_version + 1
            && org.name == input.request.display_name
            && self
                .db
                .org_matches_mutation_plan(org.id, &plan.plan_id)
                .await
                .map_err(RpcError::internal)?;
        if !exact_recovery {
            if org.resource_version != input.baseline_resource_version
                || !self
                    .db
                    .update_org_profile(
                        org.id,
                        &input.request.display_name,
                        input.baseline_resource_version,
                        &plan.plan_id,
                    )
                    .await
                    .map_err(RpcError::internal)?
            {
                return Err(RpcError::FailedPrecondition(
                    "organization changed after planning".to_string(),
                ));
            }
            org = self.org_or_not_found(&input.request.slug).await?;
        }
        let response = pb::OrganizationResponse {
            organization: Some(organization_message(&org)),
        };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// Plans organization offboarding under an exact resource version.
    ///
    /// # Errors
    ///
    /// Returns an authentication, authorization, stale-version, or persistence
    /// error.
    pub async fn plan_delete_organization(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanDeleteOrganizationRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let org = self.org_or_not_found(&req.slug).await?;
        self.require_permission(&claims, Permission::IamAdmin, &Scope::parse(&org.stable_id))
            .await?;
        if req.expected_resource_version.is_empty()
            || parse_resource_version(&req.expected_resource_version, org.resource_version)?
                != org.resource_version
        {
            return Err(RpcError::FailedPrecondition(
                "organization resource version is required and must be current".to_string(),
            ));
        }
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let input = OrganizationDeletePlanInput {
            request: req,
            org_id: org.id,
            baseline_resource_version: org.resource_version,
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            "delete_organization",
            &org.stable_id,
            &input,
            &idempotency_key,
            vec![format!(
                "soft-delete organization '{}' and begin its 30-day purge grace",
                org.slug
            )],
            vec!["serving stops immediately; external storage purge is separate".to_string()],
            Some(confirmation_hash),
        )
        .await
    }

    /// Applies organization offboarding exactly once.
    ///
    /// # Errors
    ///
    /// Returns an authentication, confirmation, authorization, stale-plan, or
    /// persistence error.
    pub async fn apply_delete_organization(
        &self,
        auth: Option<&str>,
        req: pb::ApplyOrganizationMutationRequest,
    ) -> Result<pb::DeleteTopologyResourceResponse, RpcError> {
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                "delete_organization",
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            "delete_organization",
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, OrganizationDeletePlanInput) = self
            .load_control_plan(
                auth,
                &req.plan_id,
                "delete_organization",
                Some(&req.confirmation_hash),
            )
            .await?;
        let org = self
            .db
            .org_by_slug_including_deleted(&input.request.slug)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("organization"))?;
        let claims = self.require_claims(auth)?;
        self.require_permission(&claims, Permission::IamAdmin, &Scope::parse(&org.stable_id))
            .await?;
        if org.id != input.org_id {
            return Err(RpcError::FailedPrecondition(
                "organization identity changed after planning".to_string(),
            ));
        }
        let exact_recovery = org.resource_version == input.baseline_resource_version + 1
            && self
                .db
                .org_matches_mutation_plan(org.id, &plan.plan_id)
                .await
                .map_err(RpcError::internal)?;
        if !exact_recovery
            && (org.resource_version != input.baseline_resource_version
                || !self
                    .db
                    .soft_delete_org_at_version(
                        org.id,
                        ORGANIZATION_DELETE_GRACE_SECS,
                        input.baseline_resource_version,
                        &plan.plan_id,
                    )
                    .await
                    .map_err(RpcError::internal)?)
        {
            return Err(RpcError::FailedPrecondition(
                "organization changed after planning".to_string(),
            ));
        }
        if let Err(error) = self
            .db
            .record_audit(
                &claims.owner_kind,
                Some(claims.owner_id),
                &claims.sub,
                "topology.organization.delete",
                &org.stable_id,
                None,
                None,
                None,
                Some(&org.slug),
            )
            .await
        {
            tracing::warn!(error = %format!("{error:#}"), "recording organization deletion audit");
        }
        let response = pb::DeleteTopologyResourceResponse { deleted: true };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// `ProjectService.ListProjects` — an org's projects, ordered by path.
    ///
    /// The project tree is org-internal: the caller must present a bearer JWT
    /// granting [`Permission::Read`] on the org scope. An anonymous or
    /// non-member caller is denied, so the project layout never leaks across
    /// tenants.
    ///
    /// # Errors
    ///
    /// Returns [`RpcError::Unauthenticated`] for a missing/invalid bearer JWT,
    /// [`RpcError::NotFound`] for an unknown org,
    /// [`RpcError::PermissionDenied`] when the caller lacks `Read` on the org
    /// scope, and [`RpcError::Internal`] on database failure.
    pub async fn list_projects(
        &self,
        auth: Option<&str>,
        req: pb::ListProjectsRequest,
    ) -> Result<pb::ListProjectsResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let org = self.org_or_not_found(&req.org_slug).await?;
        self.require_permission(&claims, Permission::Read, &Scope::parse(&org.stable_id))
            .await?;
        let projects: Vec<pb::Project> = self
            .db
            .list_projects(org.id)
            .await
            .map_err(RpcError::internal)?
            .into_iter()
            .map(|project| project_message(org.slug.clone(), project))
            .collect();
        let (projects, next_page_token) = paginate(projects, req.page_size, &req.page_token)?;
        Ok(pb::ListProjectsResponse {
            projects,
            next_page_token,
        })
    }

    /// Resolves a canonical storage owner scope and requires an exact permission.
    async fn storage_owner(
        &self,
        auth: Option<&str>,
        owner_scope_key: &str,
        permission: Permission,
    ) -> Result<Option<i64>, RpcError> {
        let claims = self.require_claims(auth)?;
        let scope = Scope::try_parse(owner_scope_key)
            .ok_or_else(|| RpcError::invalid("owner scope is not canonical"))?;
        let (kind, org_id, _project_id) = self
            .db
            .authorization_scope_owner(owner_scope_key)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("owner scope"))?;
        if kind == "instance" {
            self.require_permission(&claims, permission, &Scope::root())
                .await?;
            return Ok(None);
        }
        self.require_permission(&claims, permission, &scope).await?;
        Ok(org_id)
    }

    /// Resolves a canonical storage owner scope for read-only operations.
    async fn readable_storage_owner(
        &self,
        auth: Option<&str>,
        owner_scope_key: &str,
    ) -> Result<Option<i64>, RpcError> {
        self.storage_owner(auth, owner_scope_key, Permission::BindingRead)
            .await
    }

    /// Resolves a canonical storage owner scope for mutating operations.
    async fn writable_storage_owner(
        &self,
        auth: Option<&str>,
        owner_scope_key: &str,
    ) -> Result<Option<i64>, RpcError> {
        self.storage_owner(auth, owner_scope_key, Permission::BindingManage)
            .await
    }

    /// Resolves and authorizes one typed storage-binding reference.
    async fn resolve_binding_reference(
        &self,
        auth: Option<&str>,
        reference: Option<pb::BindingRef>,
    ) -> Result<crate::db::BindingRecord, RpcError> {
        let target = reference
            .and_then(|binding| binding.target)
            .ok_or_else(|| RpcError::invalid("storageBinding reference is required"))?;
        match target {
            pb::binding_ref::Target::InstanceDefault(true) => {
                self.readable_storage_owner(auth, "instance").await?;
                self.db.instance_default_binding().await
            }
            pb::binding_ref::Target::InstanceDefault(false) => {
                return Err(RpcError::invalid("instanceDefault must be true"));
            }
            pb::binding_ref::Target::Organization(reference) => {
                let org = self.org_or_not_found(&reference.org_slug).await?;
                let scope = org.stable_id;
                let org_id = self
                    .readable_storage_owner(auth, &scope)
                    .await?
                    .ok_or_else(|| {
                        RpcError::internal(anyhow::anyhow!("org scope resolved as instance"))
                    })?;
                self.db.binding_by_name(org_id, &reference.name).await
            }
        }
        .map_err(RpcError::internal)?
        .ok_or_else(|| RpcError::not_found("binding"))
    }

    /// Validates and canonicalizes a storage-binding desired spec.
    fn canonicalize_binding_spec(spec: &mut pb::BindingSpec) -> Result<(), RpcError> {
        spec.name = spec.name.trim().to_string();
        if spec.name.is_empty() {
            return Err(RpcError::invalid("binding name is required"));
        }
        match spec.provider.as_mut() {
            Some(pb::binding_spec::Provider::LocalFilesystem(provider)) => {
                provider.root_path = provider.root_path.trim().to_string();
                if !provider.root_path.starts_with('/') {
                    return Err(RpcError::invalid(
                        "local filesystem rootPath must be absolute",
                    ));
                }
            }
            Some(pb::binding_spec::Provider::S3(provider)) => {
                Self::canonicalize_object_storage_provider(
                    &mut provider.bucket,
                    &mut provider.prefix,
                    &mut provider.endpoint,
                    &mut provider.signing_region,
                    &mut provider.access_mode,
                )?;
            }
            Some(pb::binding_spec::Provider::R2(provider)) => {
                Self::canonicalize_object_storage_provider(
                    &mut provider.bucket,
                    &mut provider.prefix,
                    &mut provider.endpoint,
                    &mut provider.signing_region,
                    &mut provider.access_mode,
                )?;
            }
            Some(pb::binding_spec::Provider::DeploymentR2(_)) => {
                return Err(RpcError::invalid(
                    "deployment R2 bindings are provisioned only by the serving runtime",
                ));
            }
            None => return Err(RpcError::invalid("binding provider is required")),
        }
        Ok(())
    }

    fn canonicalize_object_storage_provider(
        bucket: &mut String,
        prefix: &mut String,
        endpoint: &mut Option<pb::StorageEndpoint>,
        signing_region: &mut String,
        access_mode: &mut String,
    ) -> Result<(), RpcError> {
        *bucket = bucket.trim().to_string();
        *prefix = prefix.trim_matches('/').to_string();
        *signing_region = signing_region.trim().to_string();
        *access_mode = access_mode.trim().to_ascii_lowercase();
        if bucket.is_empty() || signing_region.is_empty() {
            return Err(RpcError::invalid(
                "object storage requires bucket and signingRegion",
            ));
        }
        if !matches!(access_mode.as_str(), "public" | "private") {
            return Err(RpcError::invalid(
                "object storage accessMode must be public or private",
            ));
        }
        let endpoint = endpoint
            .as_mut()
            .ok_or_else(|| RpcError::invalid("object storage endpoint is required"))?;
        endpoint.scheme = endpoint.scheme.trim().to_ascii_lowercase();
        if endpoint.scheme != "https" {
            return Err(RpcError::invalid("storage endpoints must use https"));
        }
        if endpoint.port == 0 {
            endpoint.port = 443;
        }
        let authority = match endpoint.host.as_mut() {
            Some(pb::storage_endpoint::Host::DnsName(name)) => {
                *name = crate::db::canonical_delivery_hostname(name)
                    .map_err(|error| RpcError::invalid(format!("endpoint DNS name: {error:#}")))?;
                name.clone()
            }
            Some(pb::storage_endpoint::Host::Ipv4(bytes)) if bytes.len() == 4 => {
                let ip = std::net::Ipv4Addr::new(bytes[0], bytes[1], bytes[2], bytes[3]);
                if !crate::url_guard::is_global_ip(std::net::IpAddr::V4(ip)) {
                    return Err(RpcError::invalid(
                        "storage endpoint IP must be globally routable",
                    ));
                }
                ip.to_string()
            }
            Some(pb::storage_endpoint::Host::Ipv6(bytes)) if bytes.len() == 16 => {
                let octets: [u8; 16] = bytes
                    .as_slice()
                    .try_into()
                    .map_err(|_| RpcError::invalid("endpoint IPv6 length is invalid"))?;
                let ip = std::net::Ipv6Addr::from(octets);
                if !crate::url_guard::is_global_ip(std::net::IpAddr::V6(ip)) {
                    return Err(RpcError::invalid(
                        "storage endpoint IP must be globally routable",
                    ));
                }
                format!("[{ip}]")
            }
            Some(_) => return Err(RpcError::invalid("endpoint IP length is invalid")),
            None => return Err(RpcError::invalid("endpoint host is required")),
        };
        crate::url_guard::is_safe_remote_url(&format!("https://{authority}:{}/", endpoint.port))
            .map_err(|error| RpcError::invalid(format!("storage endpoint: {error:#}")))?;
        Ok(())
    }

    /// Reconstructs the final desired spec from one binding record.
    fn binding_spec_from_record(
        record: &crate::db::BindingRecord,
    ) -> Result<pb::BindingSpec, RpcError> {
        let endpoint = match (
            record.endpoint_scheme.clone(),
            record.endpoint_host_kind.as_deref(),
            record.endpoint_host_bytes.clone(),
        ) {
            (Some(scheme), Some(kind), Some(bytes)) => {
                let host = match kind {
                    "dns" => pb::storage_endpoint::Host::DnsName(
                        String::from_utf8(bytes)
                            .map_err(|error| RpcError::internal(anyhow::anyhow!(error)))?,
                    ),
                    "ipv4" => pb::storage_endpoint::Host::Ipv4(bytes),
                    "ipv6" => pb::storage_endpoint::Host::Ipv6(bytes),
                    _ => {
                        return Err(RpcError::internal(anyhow::anyhow!(
                            "invalid endpoint host kind"
                        )));
                    }
                };
                Some(pb::StorageEndpoint {
                    scheme,
                    host: Some(host),
                    port: u32::try_from(record.endpoint_port.unwrap_or_default())
                        .unwrap_or_default(),
                })
            }
            (None, None, None) => None,
            _ => {
                return Err(RpcError::internal(anyhow::anyhow!(
                    "incomplete storage endpoint"
                )));
            }
        };
        let provider = match record.kind.as_str() {
            "local_fs" => {
                pb::binding_spec::Provider::LocalFilesystem(pb::LocalFilesystemStorageProvider {
                    root_path: record.local_root_path.clone().unwrap_or_default(),
                })
            }
            "s3" => pb::binding_spec::Provider::S3(pb::S3StorageProvider {
                bucket: record.object_bucket.clone().unwrap_or_default(),
                prefix: record.object_prefix.clone().unwrap_or_default(),
                endpoint,
                signing_region: record.signing_region.clone().unwrap_or_default(),
                access_mode: record.access_mode.clone().unwrap_or_default(),
            }),
            "r2" => pb::binding_spec::Provider::R2(pb::R2StorageProvider {
                bucket: record.object_bucket.clone().unwrap_or_default(),
                prefix: record.object_prefix.clone().unwrap_or_default(),
                endpoint,
                signing_region: record.signing_region.clone().unwrap_or_default(),
                access_mode: record.access_mode.clone().unwrap_or_default(),
            }),
            "deployment_r2" => {
                pb::binding_spec::Provider::DeploymentR2(pb::DeploymentR2StorageProvider {
                    bucket_binding: record.object_bucket.clone().unwrap_or_default(),
                })
            }
            kind => {
                return Err(RpcError::internal(anyhow::anyhow!(
                    "unknown storage provider kind '{kind}'"
                )));
            }
        };
        Ok(pb::BindingSpec {
            name: record.name.clone(),
            provider: Some(provider),
        })
    }

    /// Projects a storage-binding record without exposing credential material.
    async fn binding_message(
        &self,
        record: crate::db::BindingRecord,
    ) -> Result<pb::Binding, RpcError> {
        let spec = Self::binding_spec_from_record(&record)?;
        let credentials = self
            .db
            .list_current_binding_credentials(record.id)
            .await
            .map_err(RpcError::internal)?;
        let has_valid_credential = |purpose: &str| {
            credentials.iter().any(|credential| {
                credential.purpose == purpose && credential.validation_state == "valid"
            })
        };
        let local_filesystem = record.kind == "local_fs";
        let public_object_store = record.access_mode.as_deref() == Some("public");
        let mut capabilities = pb::BindingCapabilities {
            reads_supported: local_filesystem
                || public_object_store
                || has_valid_credential("read"),
            writes_supported: false,
            conditional_writes_supported: false,
            deletes_supported: record.kind == "s3" && has_valid_credential("delete"),
            lists_supported: local_filesystem
                || public_object_store
                || has_valid_credential("list"),
            presigns_supported: !local_filesystem && has_valid_credential("presign"),
        };
        let health = if let Some(state) = self
            .db
            .binding_write_state(record.id)
            .await
            .map_err(RpcError::internal)?
        {
            if let Some(revision_number) = state.current_write_revision {
                let revision = self
                    .db
                    .binding_write_revision(record.id, revision_number)
                    .await
                    .map_err(RpcError::internal)?;
                let observation = self
                    .db
                    .binding_write_observation(record.id, revision_number)
                    .await
                    .map_err(RpcError::internal)?;
                if let Some(revision) = revision {
                    capabilities.writes_supported = revision.writes_supported;
                    capabilities.conditional_writes_supported =
                        revision.conditional_writes_supported;
                }
                observation.map(|observation| pb::BindingHealth {
                    state: observation.state,
                    observed_at: observation.validated_at.unwrap_or_default(),
                    error: observation.error.unwrap_or_default(),
                })
            } else {
                None
            }
        } else {
            None
        };
        let grant_records = self
            .db
            .list_consumer_scope_grants(crate::db::GrantResource::Binding {
                id: record.id,
                stable_id: &record.stable_id,
            })
            .await
            .map_err(RpcError::internal)?;
        let mut grants = Vec::with_capacity(grant_records.len());
        for grant in grant_records {
            let pins = self
                .db
                .consumer_scope_grant_pin_records(
                    crate::db::GrantResource::Binding {
                        id: record.id,
                        stable_id: &record.stable_id,
                    },
                    &grant.consumer_scope_key,
                )
                .await
                .map_err(RpcError::internal)?;
            grants.push(Self::binding_grant_message(&record.stable_id, grant, pins));
        }
        Ok(pb::Binding {
            stable_id: record.stable_id,
            owner_scope_key: record.owner_scope_key,
            spec: Some(spec),
            capabilities: Some(capabilities),
            health,
            grants,
            resource_version: record.resource_version.to_string(),
            created_at: record.created_at,
            updated_at: record.updated_at,
        })
    }

    /// Returns normalized endpoint columns for persistence.
    fn storage_endpoint_parts(
        spec: &pb::BindingSpec,
    ) -> (
        Option<&str>,
        Option<&'static str>,
        Option<&[u8]>,
        Option<i64>,
    ) {
        let endpoint = match spec.provider.as_ref() {
            Some(pb::binding_spec::Provider::S3(provider)) => provider.endpoint.as_ref(),
            Some(pb::binding_spec::Provider::R2(provider)) => provider.endpoint.as_ref(),
            _ => None,
        };
        let Some(endpoint) = endpoint else {
            return (None, None, None, None);
        };
        let (kind, bytes) = match endpoint.host.as_ref() {
            Some(pb::storage_endpoint::Host::DnsName(name)) => ("dns", name.as_bytes()),
            Some(pb::storage_endpoint::Host::Ipv4(bytes)) => ("ipv4", bytes.as_slice()),
            Some(pb::storage_endpoint::Host::Ipv6(bytes)) => ("ipv6", bytes.as_slice()),
            None => return (None, None, None, None),
        };
        (
            Some(endpoint.scheme.as_str()),
            Some(kind),
            Some(bytes),
            Some(i64::from(endpoint.port)),
        )
    }

    /// `BindingService.ListBindings` lists one authorized owner scope.
    ///
    /// # Errors
    ///
    /// Returns an authorization, pagination, or persistence error.
    pub async fn list_bindings_v1(
        &self,
        auth: Option<&str>,
        req: pb::ListBindingsRequest,
    ) -> Result<pb::ListBindingsResponse, RpcError> {
        self.readable_storage_owner(auth, &req.owner_scope_key)
            .await?;
        let records = self
            .db
            .list_bindings_by_scope(&req.owner_scope_key)
            .await
            .map_err(RpcError::internal)?;
        let mut bindings = Vec::with_capacity(records.len());
        for record in records {
            bindings.push(self.binding_message(record).await?);
        }
        let (bindings, next_page_token) = paginate(bindings, req.page_size, &req.page_token)?;
        Ok(pb::ListBindingsResponse {
            bindings,
            next_page_token,
        })
    }

    /// `BindingService.GetBinding` reads one typed binding reference.
    ///
    /// # Errors
    ///
    /// Returns an authorization, malformed-reference, not-found, or persistence error.
    pub async fn get_binding_v1(
        &self,
        auth: Option<&str>,
        req: pb::GetBindingRequest,
    ) -> Result<pb::GetBindingResponse, RpcError> {
        let record = self.resolve_binding_reference(auth, req.binding).await?;
        Ok(pb::GetBindingResponse {
            binding: Some(self.binding_message(record).await?),
        })
    }

    /// `BindingService.PlanCreateBinding` persists an immutable create plan.
    ///
    /// # Errors
    ///
    /// Returns an authorization, validation, conflict, or persistence error.
    pub async fn plan_create_binding(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanBindingMutationRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        if req.stable_id.trim().is_empty() || !req.expected_resource_version.is_empty() {
            return Err(RpcError::invalid(
                "create requires stableId and forbids expectedResourceVersion",
            ));
        }
        if !req.update_mask.is_empty() {
            return Err(RpcError::invalid("create forbids updateMask"));
        }
        let org_id = self
            .writable_storage_owner(auth, &req.owner_scope_key)
            .await?;
        req.stable_id = req.stable_id.trim().to_string();
        let spec = req
            .spec
            .as_mut()
            .ok_or_else(|| RpcError::invalid("spec is required"))?;
        Self::canonicalize_binding_spec(spec)?;
        if org_id.is_some()
            && matches!(
                spec.provider.as_ref(),
                Some(pb::binding_spec::Provider::LocalFilesystem(_))
                    | Some(pb::binding_spec::Provider::DeploymentR2(_))
            )
        {
            return Err(RpcError::invalid(
                "organization bindings must use an external s3 or r2 provider",
            ));
        }
        if self
            .db
            .binding_by_stable_id(&req.stable_id)
            .await
            .map_err(RpcError::internal)?
            .is_some()
        {
            return Err(RpcError::AlreadyExists(
                "binding stable id already exists".to_string(),
            ));
        }
        if self
            .db
            .list_bindings_by_scope(&req.owner_scope_key)
            .await
            .map_err(RpcError::internal)?
            .iter()
            .any(|binding| binding.name == spec.name)
        {
            return Err(RpcError::AlreadyExists(
                "binding name already exists in owner scope".to_string(),
            ));
        }
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let input = BindingMutationPlanInput {
            request: req,
            org_id,
            binding_db_id: None,
            baseline_resource_version: None,
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            "create_binding",
            &input.request.owner_scope_key,
            &input,
            &idempotency_key,
            vec![format!("create binding '{}'", input.request.stable_id)],
            Vec::new(),
            Some(confirmation_hash),
        )
        .await
    }

    /// `BindingService.CreateBinding` applies a create plan exactly once.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, conflict, or persistence error.
    pub async fn apply_create_binding(
        &self,
        auth: Option<&str>,
        req: pb::ApplyBindingMutationRequest,
    ) -> Result<pb::BindingResponse, RpcError> {
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                "create_binding",
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            "create_binding",
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, BindingMutationPlanInput) = self
            .load_control_plan(
                auth,
                &req.plan_id,
                "create_binding",
                Some(&req.confirmation_hash),
            )
            .await?;
        if self
            .writable_storage_owner(auth, &input.request.owner_scope_key)
            .await?
            != input.org_id
        {
            return Err(RpcError::FailedPrecondition(
                "binding owner changed after planning".to_string(),
            ));
        }
        if let Some(existing) = self
            .db
            .binding_by_stable_id(&input.request.stable_id)
            .await
            .map_err(RpcError::internal)?
        {
            let expected =
                input.request.spec.as_ref().ok_or_else(|| {
                    RpcError::internal(anyhow::anyhow!("binding plan has no spec"))
                })?;
            if existing.owner_scope_key == input.request.owner_scope_key
                && Self::binding_spec_from_record(&existing)? == *expected
            {
                let response = pb::BindingResponse {
                    binding: Some(self.binding_message(existing).await?),
                };
                self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
                    .await?;
                return Ok(response);
            }
            return Err(RpcError::AlreadyExists(
                "binding stable id has different state".to_string(),
            ));
        }
        let spec = input
            .request
            .spec
            .as_ref()
            .ok_or_else(|| RpcError::internal(anyhow::anyhow!("binding plan has no spec")))?;
        let (scheme, host_kind, host_bytes, port) = Self::storage_endpoint_parts(spec);
        let (kind, local_root_path, object_bucket, object_prefix, signing_region, access_mode) =
            match spec.provider.as_ref() {
                Some(pb::binding_spec::Provider::LocalFilesystem(provider)) => (
                    "local_fs",
                    Some(provider.root_path.as_str()),
                    None,
                    None,
                    None,
                    None,
                ),
                Some(pb::binding_spec::Provider::S3(provider)) => (
                    "s3",
                    None,
                    Some(provider.bucket.as_str()),
                    Some(provider.prefix.as_str()),
                    Some(provider.signing_region.as_str()),
                    Some(provider.access_mode.as_str()),
                ),
                Some(pb::binding_spec::Provider::R2(provider)) => (
                    "r2",
                    None,
                    Some(provider.bucket.as_str()),
                    Some(provider.prefix.as_str()),
                    Some(provider.signing_region.as_str()),
                    Some(provider.access_mode.as_str()),
                ),
                Some(pb::binding_spec::Provider::DeploymentR2(_)) => {
                    return Err(RpcError::internal(anyhow::anyhow!(
                        "deployment R2 provider escaped plan validation"
                    )));
                }
                None => {
                    return Err(RpcError::internal(anyhow::anyhow!(
                        "binding plan has no provider"
                    )));
                }
            };
        self.db
            .create_topology_binding(
                input.org_id,
                &input.request.stable_id,
                &input.request.owner_scope_key,
                &spec.name,
                kind,
                local_root_path,
                object_bucket,
                object_prefix,
                scheme,
                host_kind,
                host_bytes,
                port,
                signing_region,
                access_mode,
            )
            .await
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        let record = self
            .db
            .binding_by_stable_id(&input.request.stable_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::internal(anyhow::anyhow!("created binding disappeared")))?;
        let response = pb::BindingResponse {
            binding: Some(self.binding_message(record).await?),
        };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }
    /// `BindingService.PlanDeleteBinding` persists reviewed blockers and CAS.
    ///
    /// # Errors
    ///
    /// Returns an authorization, stale-version, blocker, or persistence error.
    pub async fn plan_delete_binding(
        &self,
        auth: Option<&str>,
        req: pb::PlanDeleteTopologyResourceRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let binding = self
            .db
            .binding_by_stable_id(&req.stable_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        let owner_scope_key = binding.owner_scope_key.clone();
        let org_id = self.writable_storage_owner(auth, &owner_scope_key).await?;
        if binding.is_instance_default {
            return Err(RpcError::FailedPrecondition(
                "the instance-default binding cannot be deleted".to_string(),
            ));
        }
        let expected = parse_resource_version(
            req.expected_resource_version
                .as_deref()
                .ok_or_else(|| RpcError::invalid("expectedResourceVersion is required"))?,
            binding.resource_version,
        )?;
        if expected != binding.resource_version {
            return Err(RpcError::FailedPrecondition(
                "binding resource version is stale".to_string(),
            ));
        }
        let blockers = self
            .db
            .binding_delete_blockers(binding.id)
            .await
            .map_err(RpcError::internal)?;
        if !blockers.is_empty() {
            return Err(RpcError::FailedPrecondition(format!(
                "binding is still referenced by {}",
                blockers.join(", ")
            )));
        }
        let input = BindingDeletePlanInput {
            stable_id: req.stable_id,
            owner_scope_key: owner_scope_key.clone(),
            org_id,
            binding_db_id: binding.id,
            baseline_resource_version: expected,
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            "delete_binding",
            &owner_scope_key,
            &input,
            &req.idempotency_key,
            vec![format!("delete binding '{}'", input.stable_id)],
            vec!["credential revisions are deleted with the binding".to_string()],
            Some(confirmation_hash),
        )
        .await
    }

    /// `BindingService.DeleteBinding` applies a deletion plan exactly once.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, stale-version, blocker, or persistence error.
    pub async fn apply_delete_binding(
        &self,
        auth: Option<&str>,
        req: pb::ApplyDeleteTopologyResourceRequest,
    ) -> Result<pb::DeleteTopologyResourceResponse, RpcError> {
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                "delete_binding",
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            "delete_binding",
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, BindingDeletePlanInput) = self
            .load_control_plan(
                auth,
                &req.plan_id,
                "delete_binding",
                Some(&req.confirmation_hash),
            )
            .await?;
        if self
            .writable_storage_owner(auth, &input.owner_scope_key)
            .await?
            != input.org_id
        {
            return Err(RpcError::FailedPrecondition(
                "binding deletion plan target changed".to_string(),
            ));
        }
        let Some(binding) = self
            .db
            .binding_by_stable_id(&input.stable_id)
            .await
            .map_err(RpcError::internal)?
        else {
            let response = pb::DeleteTopologyResourceResponse { deleted: true };
            self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
                .await?;
            return Ok(response);
        };
        if binding.id != input.binding_db_id
            || binding.resource_version != input.baseline_resource_version
        {
            return Err(RpcError::FailedPrecondition(
                "binding changed after deletion was planned".to_string(),
            ));
        }
        let blockers = self
            .db
            .binding_delete_blockers(binding.id)
            .await
            .map_err(RpcError::internal)?;
        if !blockers.is_empty() {
            return Err(RpcError::FailedPrecondition(format!(
                "binding acquired live references: {}",
                blockers.join(", ")
            )));
        }
        if !self
            .db
            .delete_topology_binding(binding.id, input.baseline_resource_version)
            .await
            .map_err(RpcError::internal)?
        {
            return Err(RpcError::FailedPrecondition(
                "binding changed while deletion was applied".to_string(),
            ));
        }
        let response = pb::DeleteTopologyResourceResponse { deleted: true };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// Projects a credential revision without resolving or exposing secret material.
    fn binding_credential_message(
        stable_id: &str,
        record: crate::db::BindingCredentialRevisionRecord,
    ) -> pb::BindingCredential {
        pb::BindingCredential {
            binding_id: stable_id.to_string(),
            purpose: record.purpose,
            generation: record.generation,
            secret_version_ref: record.secret_version_ref,
            validation_state: record.validation_state,
            validated_at: record.validated_at.unwrap_or_default(),
            validation_error: record.validation_error.unwrap_or_default(),
            credential_fingerprint: record.credential_fingerprint,
            created_at: record.created_at,
            resource_version: record.head_resource_version.to_string(),
        }
    }

    /// Persists a credential set/rotation plan after resolving exact head state.
    async fn plan_binding_credential(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanBindingCredentialRequest,
        rotate: bool,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        if req.secret_version_ref.trim().is_empty() {
            return Err(RpcError::invalid("secretVersionRef is required"));
        }
        if !matches!(
            req.purpose.as_str(),
            "read" | "write" | "delete" | "list" | "presign"
        ) {
            return Err(RpcError::invalid("credential purpose is invalid"));
        }
        let binding = self
            .db
            .binding_by_stable_id(&req.binding_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        let owner_scope_key = binding.owner_scope_key.clone();
        self.writable_storage_owner(auth, &owner_scope_key).await?;
        if !matches!(binding.kind.as_str(), "s3" | "r2")
            || binding.access_mode.as_deref() != Some("private")
        {
            return Err(RpcError::invalid(
                "credential revisions are supported only by private external s3/r2 bindings",
            ));
        }
        let expected_binding_version =
            parse_resource_version(&req.expected_resource_version, binding.resource_version)?;
        if expected_binding_version != binding.resource_version {
            return Err(RpcError::FailedPrecondition(
                "binding changed before credential planning".to_string(),
            ));
        }
        let current = self
            .db
            .current_binding_credential(binding.id, &req.purpose)
            .await
            .map_err(RpcError::internal)?;
        let current_generation = current.as_ref().map_or(0, |record| record.generation);
        if current_generation != req.expected_current_generation
            || rotate != (current_generation > 0)
        {
            return Err(RpcError::FailedPrecondition(
                "credential generation does not match set/rotate semantics".to_string(),
            ));
        }
        req.secret_version_ref = req.secret_version_ref.trim().to_string();
        crate::secret_version::validate_secret_version_ref(&req.secret_version_ref)
            .map_err(|error| RpcError::invalid(format!("invalid secretVersionRef: {error:#}")))?;
        req.credential_fingerprint = req.credential_fingerprint.trim().to_ascii_lowercase();
        if req.credential_fingerprint.len() != 64
            || !req
                .credential_fingerprint
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit())
        {
            return Err(RpcError::invalid(
                "credentialFingerprint is required and must be SHA-256 hex",
            ));
        }
        let secrets = self.secret_versions.as_deref().ok_or_else(|| {
            RpcError::FailedPrecondition("secret-version provider is not configured".to_string())
        })?;
        let resolved = secrets
            .resolve(&req.secret_version_ref)
            .await
            .map_err(|error| {
                RpcError::FailedPrecondition(format!(
                    "secret version cannot be resolved: {error:#}"
                ))
            })?;
        crate::secret_version::verify_secret_fingerprint(&resolved, &req.credential_fingerprint)
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        drop(resolved);
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let credential_fingerprint = req.credential_fingerprint.clone();
        let input = BindingCredentialPlanInput {
            request: req,
            binding_db_id: binding.id,
            owner_scope_key: owner_scope_key.clone(),
            credential_fingerprint,
        };
        let plan_kind = if rotate {
            "rotate_binding_credential"
        } else {
            "set_binding_credential"
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            plan_kind,
            &owner_scope_key,
            &input,
            &idempotency_key,
            vec![format!(
                "{} '{}' credential generation {}",
                if rotate { "rotate" } else { "set" },
                input.request.purpose,
                current_generation + 1
            )],
            Vec::new(),
            Some(confirmation_hash),
        )
        .await
    }

    /// Plans initial credential configuration.
    ///
    /// # Errors
    ///
    /// Returns an authorization, validation, stale-version, or persistence error.
    pub async fn plan_set_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::PlanBindingCredentialRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_binding_credential(auth, req, false).await
    }

    /// Plans credential rotation.
    ///
    /// # Errors
    ///
    /// Returns an authorization, validation, stale-version, or persistence error.
    pub async fn plan_rotate_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::PlanBindingCredentialRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_binding_credential(auth, req, true).await
    }

    /// Applies a credential set/rotation plan with exact-result recovery.
    async fn apply_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::ApplyBindingCredentialRequest,
        rotate: bool,
    ) -> Result<pb::BindingCredentialResponse, RpcError> {
        let plan_kind = if rotate {
            "rotate_binding_credential"
        } else {
            "set_binding_credential"
        };
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                plan_kind,
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            plan_kind,
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, BindingCredentialPlanInput) = self
            .load_control_plan(auth, &req.plan_id, plan_kind, Some(&req.confirmation_hash))
            .await?;
        self.writable_storage_owner(auth, &input.owner_scope_key)
            .await?;
        let binding = self
            .db
            .binding_by_stable_id(&input.request.binding_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        if binding.id != input.binding_db_id {
            return Err(RpcError::FailedPrecondition(
                "binding identity changed after credential planning".to_string(),
            ));
        }
        let claims = self.require_claims(auth)?;
        let record = self
            .db
            .set_binding_credential_revision(
                binding.id,
                &input.request.purpose,
                &input.request.secret_version_ref,
                input.request.expected_current_generation,
                &input.credential_fingerprint,
                &claims.sub,
            )
            .await
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        let response = pb::BindingCredentialResponse {
            credential: Some(Self::binding_credential_message(
                &input.request.binding_id,
                record,
            )),
        };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// Applies initial credential configuration.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, stale-plan, or persistence error.
    pub async fn apply_set_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::ApplyBindingCredentialRequest,
    ) -> Result<pb::BindingCredentialResponse, RpcError> {
        self.apply_binding_credential(auth, req, false).await
    }

    /// Applies credential rotation.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, stale-plan, or persistence error.
    pub async fn apply_rotate_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::ApplyBindingCredentialRequest,
    ) -> Result<pb::BindingCredentialResponse, RpcError> {
        self.apply_binding_credential(auth, req, true).await
    }

    /// Queues controller validation of the current credential generation.
    ///
    /// # Errors
    ///
    /// Returns an authorization, validation, stale-version, or scheduling error.
    async fn execute_validate_binding_credential(
        &self,
        auth: Option<&str>,
        req: pb::PlanValidateBindingCredentialRequest,
    ) -> Result<pb::OperationResponse, RpcError> {
        if req.idempotency_key.is_empty() {
            return Err(RpcError::invalid("idempotencyKey is required"));
        }
        let binding = self
            .db
            .binding_by_stable_id(&req.binding_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        self.writable_storage_owner(auth, &binding.owner_scope_key)
            .await?;
        let current = if req.generation == 0 {
            self.db
                .current_binding_credential(binding.id, &req.purpose)
                .await
                .map_err(RpcError::internal)?
        } else {
            self.db
                .binding_credential_revision(binding.id, &req.purpose, req.generation)
                .await
                .map_err(RpcError::internal)?
        }
        .ok_or_else(|| RpcError::not_found("binding credential"))?;
        let expected = parse_resource_version(
            &req.expected_resource_version,
            current.head_resource_version,
        )?;
        if !matches!(
            req.purpose.as_str(),
            "read" | "write" | "delete" | "list" | "presign"
        ) {
            return Err(RpcError::invalid(
                "purpose must be read, write, delete, list, or presign",
            ));
        }
        let operation_id = hex::encode(Sha256::digest(
            format!(
                "storage-credential-probe-v1\0{}\0{}\0{}\0{}\0{}",
                binding.stable_id, req.purpose, current.generation, expected, req.idempotency_key
            )
            .as_bytes(),
        ));
        let operation = self
            .topology_probes
            .schedule(
                &operation_id,
                crate::topology_probe::TopologyProbe::StorageCredential {
                    stable_id: binding.stable_id,
                    binding_id: binding.id,
                    binding_resource_version: binding.resource_version,
                    purpose: req.purpose,
                    generation: current.generation,
                    credential_head_resource_version: expected,
                },
            )
            .await
            .map_err(|error| {
                RpcError::FailedPrecondition(format!(
                    "schedule storage credential probe: {error:#}"
                ))
            })?;
        Ok(pb::OperationResponse {
            operation: Some(pb::OperationRef {
                operation_id: operation.operation_id,
                kind: operation.operation_kind,
                state: operation.state,
                created_at: operation.created_at,
            }),
        })
    }

    /// Projects one binding consumer-scope grant and its live pin impacts.
    fn binding_grant_message(
        stable_id: &str,
        record: crate::db::ConsumerScopeGrantRecord,
        pins: Vec<crate::db::ConsumerScopeGrantPinRecord>,
    ) -> pb::ConsumerScopeGrant {
        let pins = pins
            .into_iter()
            .map(Self::topology_pin_impact_message)
            .collect::<Vec<_>>();
        pb::ConsumerScopeGrant {
            resource_kind: "binding".to_string(),
            resource_stable_id: stable_id.to_string(),
            resource_generation: 0,
            consumer_scope_key: record.consumer_scope_key,
            grant_generation: record.grant_generation,
            grant_kind: record.grant_kind,
            state: record.state,
            granted_by: record.granted_by,
            granted_at: record.granted_at,
            revoked_by: record.revoked_by.unwrap_or_default(),
            revoked_at: record.revoked_at.unwrap_or_default(),
            live_pin_count: u64::try_from(pins.len()).unwrap_or_default(),
            live_pin_impacts: pins,
            resource_version: record.resource_version.to_string(),
        }
    }

    /// Persists a binding grant/revoke plan with exact live-pin preconditions.
    async fn plan_binding_grant(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanConsumerScopeGrantRequest,
        revoke: bool,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        if req.resource_kind != "binding" || req.consumer_scope_key.is_empty() {
            return Err(RpcError::invalid(
                "resourceKind must be binding and consumerScopeKey is required",
            ));
        }
        let binding = self
            .db
            .binding_by_stable_id(&req.resource_stable_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        let owner_scope_key = binding.owner_scope_key.clone();
        self.writable_storage_owner(auth, &owner_scope_key).await?;
        // Bindings are stable, non-generational grant targets. Their mutable
        // resource version is carried separately by grant update requests and
        // must not be confused with the generation field used by gateways.
        if req.resource_generation != 0 {
            return Err(RpcError::invalid("binding resourceGeneration must be zero"));
        }
        let grants = self
            .db
            .list_consumer_scope_grants(crate::db::GrantResource::Binding {
                id: binding.id,
                stable_id: &req.resource_stable_id,
            })
            .await
            .map_err(RpcError::internal)?;
        let existing = grants
            .iter()
            .find(|grant| grant.consumer_scope_key == req.consumer_scope_key);
        let baseline = existing.map(|grant| grant.resource_version);
        let pin_resolutions = if revoke {
            let grant = existing.ok_or_else(|| RpcError::not_found("consumer grant"))?;
            let pins = self
                .db
                .consumer_scope_grant_pin_records(
                    crate::db::GrantResource::Binding {
                        id: binding.id,
                        stable_id: &req.resource_stable_id,
                    },
                    &req.consumer_scope_key,
                )
                .await
                .map_err(RpcError::internal)?;
            if grant.grant_kind != "explicit" || grant.state != "active" {
                return Err(RpcError::FailedPrecondition(
                    "only an active explicit grant may be revoked".to_string(),
                ));
            }
            if parse_resource_version(&req.expected_resource_version, grant.resource_version)?
                != grant.resource_version
            {
                return Err(RpcError::FailedPrecondition(
                    "consumer grant resource version is stale".to_string(),
                ));
            }
            self.seal_grant_pin_resolutions(auth, &pins, &req.pin_resolutions)
                .await?
        } else if let Some(grant) = existing {
            if !req.expected_resource_version.is_empty()
                && parse_resource_version(&req.expected_resource_version, grant.resource_version)?
                    != grant.resource_version
            {
                return Err(RpcError::FailedPrecondition(
                    "consumer grant resource version is stale".to_string(),
                ));
            }
            if !req.pin_resolutions.is_empty() {
                return Err(RpcError::invalid("grant creation forbids pinResolutions"));
            }
            Vec::new()
        } else if !req.expected_resource_version.is_empty() {
            return Err(RpcError::invalid(
                "new consumer grants forbid expectedResourceVersion",
            ));
        } else {
            if !req.pin_resolutions.is_empty() {
                return Err(RpcError::invalid("grant creation forbids pinResolutions"));
            }
            Vec::new()
        };
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let input = BindingGrantPlanInput {
            request: req,
            binding_db_id: binding.id,
            owner_scope_key: owner_scope_key.clone(),
            baseline_grant_resource_version: baseline,
            pin_resolutions,
        };
        let plan_kind = if revoke {
            "revoke_binding_scope"
        } else {
            "grant_binding_scope"
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            plan_kind,
            &owner_scope_key,
            &input,
            &idempotency_key,
            vec![format!(
                "{} binding access for '{}'",
                if revoke { "revoke" } else { "grant" },
                input.request.consumer_scope_key
            )],
            Vec::new(),
            Some(confirmation_hash),
        )
        .await
    }

    /// Plans a consumer-scope grant.
    pub async fn plan_grant_binding_scope(
        &self,
        auth: Option<&str>,
        req: pb::PlanConsumerScopeGrantRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_binding_grant(auth, req, false).await
    }

    /// Plans a consumer-scope revocation.
    pub async fn plan_revoke_binding_scope(
        &self,
        auth: Option<&str>,
        req: pb::PlanConsumerScopeGrantRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_binding_grant(auth, req, true).await
    }

    /// Applies a binding scope grant/revocation plan exactly once.
    async fn apply_binding_grant(
        &self,
        auth: Option<&str>,
        req: pb::ApplyConsumerScopeGrantRequest,
        revoke: bool,
    ) -> Result<pb::ConsumerScopeGrantResponse, RpcError> {
        let plan_kind = if revoke {
            "revoke_binding_scope"
        } else {
            "grant_binding_scope"
        };
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                plan_kind,
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            plan_kind,
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, BindingGrantPlanInput) = self
            .load_control_plan(auth, &req.plan_id, plan_kind, Some(&req.confirmation_hash))
            .await?;
        self.writable_storage_owner(auth, &input.owner_scope_key)
            .await?;
        let binding = self
            .db
            .binding_by_stable_id(&input.request.resource_stable_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        if binding.id != input.binding_db_id {
            return Err(RpcError::FailedPrecondition(
                "binding identity changed after grant planning".to_string(),
            ));
        }
        let claims = self.require_claims(auth)?;
        if revoke && !input.pin_resolutions.is_empty() {
            let resource = crate::db::GrantResource::Binding {
                id: binding.id,
                stable_id: &input.request.resource_stable_id,
            };
            let record = self
                .db
                .load_consumer_scope_grant(resource, &input.request.consumer_scope_key)
                .await
                .map_err(RpcError::internal)?
                .ok_or_else(|| RpcError::not_found("binding consumer grant"))?;
            let coordination_operation = self
                .schedule_grant_revocation(
                    &plan.plan_id,
                    "binding",
                    &input.request.resource_stable_id,
                    input.request.resource_generation,
                    &input.request.consumer_scope_key,
                    input.baseline_grant_resource_version.ok_or_else(|| {
                        RpcError::internal(anyhow::anyhow!("revoke plan has no grant version"))
                    })?,
                    input.pin_resolutions,
                    &claims.sub,
                    &req.idempotency_key,
                    Permission::BindingGrant,
                )
                .await?;
            let response = pb::ConsumerScopeGrantResponse {
                grant: Some(Self::binding_grant_message(
                    &input.request.resource_stable_id,
                    record,
                    self.db
                        .consumer_scope_grant_pin_records(
                            resource,
                            &input.request.consumer_scope_key,
                        )
                        .await
                        .map_err(RpcError::internal)?,
                )),
                coordination_operation: Some(coordination_operation),
            };
            self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
                .await?;
            return Ok(response);
        }
        if revoke {
            if let Some((record, pins)) = self
                .db
                .list_consumer_scope_grants(crate::db::GrantResource::Binding {
                    id: binding.id,
                    stable_id: &input.request.resource_stable_id,
                })
                .await
                .map_err(RpcError::internal)?
                .into_iter()
                .find(|grant| grant.consumer_scope_key == input.request.consumer_scope_key)
                .map(|grant| (grant, Vec::new()))
            {
                if record.state == "revoked"
                    && Some(record.resource_version)
                        == input
                            .baseline_grant_resource_version
                            .map(|version| version + 1)
                {
                    let response = pb::ConsumerScopeGrantResponse {
                        grant: Some(Self::binding_grant_message(
                            &input.request.resource_stable_id,
                            record,
                            pins,
                        )),
                        coordination_operation: None,
                    };
                    self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
                        .await?;
                    return Ok(response);
                }
            }
        }
        let record = if revoke {
            self.db
                .revoke_consumer_scope(
                    crate::db::GrantResource::Binding {
                        id: binding.id,
                        stable_id: &input.request.resource_stable_id,
                    },
                    &input.request.consumer_scope_key,
                    input.baseline_grant_resource_version.ok_or_else(|| {
                        RpcError::internal(anyhow::anyhow!("revoke plan has no grant version"))
                    })?,
                    &claims.sub,
                    &req.idempotency_key,
                )
                .await
        } else {
            self.db
                .grant_consumer_scope(
                    crate::db::GrantResource::Binding {
                        id: binding.id,
                        stable_id: &input.request.resource_stable_id,
                    },
                    &input.request.consumer_scope_key,
                    "explicit",
                    &claims.sub,
                    &req.idempotency_key,
                )
                .await
        }
        .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        let pins = self
            .db
            .consumer_scope_grant_pin_records(
                crate::db::GrantResource::Binding {
                    id: binding.id,
                    stable_id: &input.request.resource_stable_id,
                },
                &record.consumer_scope_key,
            )
            .await
            .map_err(RpcError::internal)?;
        let response = pb::ConsumerScopeGrantResponse {
            grant: Some(Self::binding_grant_message(
                &input.request.resource_stable_id,
                record,
                pins,
            )),
            coordination_operation: None,
        };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// Applies a consumer-scope grant.
    pub async fn apply_grant_binding_scope(
        &self,
        auth: Option<&str>,
        req: pb::ApplyConsumerScopeGrantRequest,
    ) -> Result<pb::ConsumerScopeGrantResponse, RpcError> {
        self.apply_binding_grant(auth, req, false).await
    }

    /// Applies a consumer-scope revocation.
    pub async fn apply_revoke_binding_scope(
        &self,
        auth: Option<&str>,
        req: pb::ApplyConsumerScopeGrantRequest,
    ) -> Result<pb::ConsumerScopeGrantResponse, RpcError> {
        self.apply_binding_grant(auth, req, true).await
    }

    /// Projects one immutable write revision with its mutable controller observation.
    async fn binding_write_revision_message(
        &self,
        stable_id: &str,
        revision: crate::db::BindingWriteRevisionRecord,
    ) -> Result<pb::BindingWriteRevision, RpcError> {
        let observation = self
            .db
            .binding_write_observation(revision.binding_id, revision.revision)
            .await
            .map_err(RpcError::internal)?;
        Ok(pb::BindingWriteRevision {
            binding_id: stable_id.to_string(),
            revision: revision.revision,
            write_credential_purpose: revision.write_credential_purpose,
            write_credential_generation: revision.write_credential_generation,
            write_credential_version_ref: revision.write_credential_version_ref,
            writes_supported: revision.writes_supported,
            conditional_writes_supported: revision.conditional_writes_supported,
            revision_fingerprint: revision.revision_fingerprint,
            capability_fingerprint: revision.capability_fingerprint,
            validation_state: observation
                .as_ref()
                .map(|observation| observation.state.clone())
                .unwrap_or_else(|| "unknown".to_string()),
            validated_at: observation
                .as_ref()
                .and_then(|observation| observation.validated_at)
                .unwrap_or_default(),
            validation_error: observation
                .as_ref()
                .and_then(|observation| observation.error.clone())
                .unwrap_or_default(),
            created_at: revision.created_at,
            resource_version: observation
                .map(|observation| observation.observation_version.to_string())
                .unwrap_or_else(|| "0".to_string()),
        })
    }

    /// Lists write revisions with bounded cursor pagination.
    pub async fn list_binding_write_revisions(
        &self,
        auth: Option<&str>,
        req: pb::ListBindingWriteRevisionsRequest,
    ) -> Result<pb::ListBindingWriteRevisionsResponse, RpcError> {
        let binding = self.resolve_binding_reference(auth, req.binding).await?;
        let stable_id = binding.stable_id.clone();
        let records = self
            .db
            .list_binding_write_revisions(binding.id)
            .await
            .map_err(RpcError::internal)?;
        let mut revisions = Vec::with_capacity(records.len());
        for revision in records {
            revisions.push(
                self.binding_write_revision_message(&stable_id, revision)
                    .await?,
            );
        }
        let (revisions, next_page_token) = paginate(revisions, req.page_size, &req.page_token)?;
        Ok(pb::ListBindingWriteRevisionsResponse {
            revisions,
            next_page_token,
        })
    }

    /// Gets one immutable write revision.
    pub async fn get_binding_write_revision(
        &self,
        auth: Option<&str>,
        req: pb::GetBindingWriteRevisionRequest,
    ) -> Result<pb::BindingWriteRevisionResponse, RpcError> {
        let binding = self.resolve_binding_reference(auth, req.binding).await?;
        let revision = self
            .db
            .binding_write_revision(binding.id, req.revision)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding write revision"))?;
        Ok(pb::BindingWriteRevisionResponse {
            revision: Some(
                self.binding_write_revision_message(&binding.stable_id, revision)
                    .await?,
            ),
        })
    }

    /// Reconciles a write revision's validation observation under a CAS.
    pub async fn report_binding_write_revision(
        &self,
        auth: Option<&str>,
        req: pb::ReportBindingWriteRevisionRequest,
    ) -> Result<pb::BindingWriteRevisionResponse, RpcError> {
        self.require_controller_fence(
            auth,
            &req.controller_lease_id,
            req.controller_generation,
            &req.expected_observation_version,
        )?;
        let binding = self
            .db
            .binding_by_stable_id(&req.binding_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding"))?;
        self.writable_storage_owner(auth, &binding.owner_scope_key)
            .await?;
        let observation = self
            .db
            .binding_write_observation(binding.id, req.revision)
            .await
            .map_err(RpcError::internal)?;
        let current_version = observation
            .as_ref()
            .map_or(0, |observation| observation.observation_version);
        if observation.as_ref().is_some_and(|observation| {
            observation.state == req.state
                && observation.error.as_deref()
                    == (!req.validation_error.is_empty()).then_some(req.validation_error.as_str())
        }) {
            let revision = self
                .db
                .binding_write_revision(binding.id, req.revision)
                .await
                .map_err(RpcError::internal)?
                .ok_or_else(|| RpcError::not_found("binding write revision"))?;
            return Ok(pb::BindingWriteRevisionResponse {
                revision: Some(
                    self.binding_write_revision_message(&req.binding_id, revision)
                        .await?,
                ),
            });
        }
        let expected = parse_resource_version(&req.expected_observation_version, current_version)?;
        let expected = (current_version > 0).then_some(expected);
        self.db
            .observe_binding_write_revision(
                binding.id,
                req.revision,
                &req.state,
                (!req.validation_error.is_empty()).then_some(req.validation_error.as_str()),
                expected,
            )
            .await
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        let revision = self
            .db
            .binding_write_revision(binding.id, req.revision)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::not_found("binding write revision"))?;
        Ok(pb::BindingWriteRevisionResponse {
            revision: Some(
                self.binding_write_revision_message(&req.binding_id, revision)
                    .await?,
            ),
        })
    }

    /// Projects stable topology defaults onto the public contract.
    fn stable_topology_defaults_message(
        record: crate::db::StableTopologyDefaultsRecord,
    ) -> pb::TopologyDefaults {
        pb::TopologyDefaults {
            scope_key: record.scope_key,
            binding_id: record.binding_id.unwrap_or_default(),
            domain_id: record.domain_id.unwrap_or_default(),
            endpoint_id: record.endpoint_id.unwrap_or_default(),
            endpoint_generation: record.endpoint_generation.unwrap_or_default(),
            gateway_id: record.gateway_id.unwrap_or_default(),
            gateway_generation: record.gateway_generation.unwrap_or_default(),
            resource_version: record.resource_version.to_string(),
        }
    }

    /// Projects stored defaults or the editable empty state for an unset scope.
    fn topology_defaults_or_empty(
        scope_key: &str,
        record: Option<crate::db::StableTopologyDefaultsRecord>,
    ) -> pb::TopologyDefaults {
        record
            .map(Self::stable_topology_defaults_message)
            .unwrap_or_else(|| pb::TopologyDefaults {
                scope_key: scope_key.to_string(),
                ..Default::default()
            })
    }

    /// Returns instance topology defaults.
    pub async fn get_instance_topology_defaults(
        &self,
        auth: Option<&str>,
        _req: pb::GetInstanceTopologyDefaultsRequest,
    ) -> Result<pb::TopologyDefaultsResponse, RpcError> {
        self.writable_storage_owner(auth, "instance").await?;
        let defaults = self
            .db
            .stable_topology_defaults("instance")
            .await
            .map_err(RpcError::internal)?;
        Ok(pb::TopologyDefaultsResponse {
            defaults: Some(Self::topology_defaults_or_empty("instance", defaults)),
        })
    }

    /// Returns organization topology defaults.
    pub async fn get_organization_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::GetOrganizationTopologyDefaultsRequest,
    ) -> Result<pb::TopologyDefaultsResponse, RpcError> {
        let scope_key = self.org_or_not_found(&req.org_slug).await?.stable_id;
        self.writable_storage_owner(auth, &scope_key).await?;
        let defaults = self
            .db
            .stable_topology_defaults(&scope_key)
            .await
            .map_err(RpcError::internal)?;
        Ok(pb::TopologyDefaultsResponse {
            defaults: Some(Self::topology_defaults_or_empty(&scope_key, defaults)),
        })
    }

    /// Persists an immutable topology-default replacement plan.
    async fn plan_set_topology_defaults(
        &self,
        auth: Option<&str>,
        mut req: pb::PlanSetTopologyDefaultsRequest,
        instance: bool,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        let claims = self.require_claims(auth)?;
        let defaults = req
            .defaults
            .as_mut()
            .ok_or_else(|| RpcError::invalid("defaults is required"))?;
        let org_id = self
            .writable_storage_owner(auth, &defaults.scope_key)
            .await?;
        if instance != org_id.is_none() {
            return Err(RpcError::invalid(
                "defaults scope does not match the selected instance/organization method",
            ));
        }
        if defaults.endpoint_id.is_empty() != (defaults.endpoint_generation == 0)
            || defaults.gateway_id.is_empty() != (defaults.gateway_generation == 0)
        {
            return Err(RpcError::invalid(
                "endpoint and gateway ids require positive paired generations",
            ));
        }
        let current = self
            .db
            .stable_topology_defaults(&defaults.scope_key)
            .await
            .map_err(RpcError::internal)?;
        let baseline = current.as_ref().map(|current| current.resource_version);
        match baseline {
            Some(version)
                if parse_resource_version(&req.expected_resource_version, version)? != version =>
            {
                return Err(RpcError::FailedPrecondition(
                    "topology defaults resource version is stale".to_string(),
                ));
            }
            None if !req.expected_resource_version.is_empty() => {
                return Err(RpcError::invalid(
                    "new topology defaults forbid expectedResourceVersion",
                ));
            }
            _ => {}
        }
        defaults.resource_version.clear();
        let idempotency_key = std::mem::take(&mut req.idempotency_key);
        let input = TopologyDefaultsPlanInput {
            defaults: defaults.clone(),
            org_id,
            baseline_resource_version: baseline,
        };
        let plan_kind = if instance {
            "set_instance_topology_defaults"
        } else {
            "set_organization_topology_defaults"
        };
        let confirmation_hash = hex::encode(Sha256::digest(
            serde_json::to_vec(&input).map_err(RpcError::internal)?,
        ));
        self.create_control_plan(
            &claims,
            plan_kind,
            &input.defaults.scope_key,
            &input,
            &idempotency_key,
            vec![format!(
                "replace topology defaults for '{}'",
                input.defaults.scope_key
            )],
            Vec::new(),
            Some(confirmation_hash),
        )
        .await
    }

    /// Plans instance topology defaults.
    pub async fn plan_set_instance_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::PlanSetTopologyDefaultsRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_set_topology_defaults(auth, req, true).await
    }

    /// Plans organization topology defaults.
    pub async fn plan_set_organization_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::PlanSetTopologyDefaultsRequest,
    ) -> Result<pb::TopologyPlanResponse, RpcError> {
        self.plan_set_topology_defaults(auth, req, false).await
    }

    /// Applies an instance or organization topology-default replacement plan.
    async fn apply_set_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::ApplySetTopologyDefaultsRequest,
        instance: bool,
    ) -> Result<pb::TopologyDefaultsResponse, RpcError> {
        let plan_kind = if instance {
            "set_instance_topology_defaults"
        } else {
            "set_organization_topology_defaults"
        };
        if let Some(response) = self
            .replayed_control_result(
                auth,
                &req.plan_id,
                plan_kind,
                Some(&req.confirmation_hash),
                &req.idempotency_key,
            )
            .await?
        {
            return Ok(response);
        }
        self.begin_control_plan_apply(
            auth,
            &req.plan_id,
            plan_kind,
            &req.idempotency_key,
            Some(&req.confirmation_hash),
        )
        .await?;
        let (plan, input): (_, TopologyDefaultsPlanInput) = self
            .load_control_plan(auth, &req.plan_id, plan_kind, Some(&req.confirmation_hash))
            .await?;
        if instance != input.org_id.is_none()
            || self
                .writable_storage_owner(auth, &input.defaults.scope_key)
                .await?
                != input.org_id
        {
            return Err(RpcError::FailedPrecondition(
                "topology-default ownership changed after planning".to_string(),
            ));
        }

        let current = self
            .db
            .stable_topology_defaults(&input.defaults.scope_key)
            .await
            .map_err(RpcError::internal)?;
        if let Some(current) = current {
            let current_message = Self::stable_topology_defaults_message(current.clone());
            let exact_recovery = current.resource_version
                == input.baseline_resource_version.unwrap_or_default() + 1
                && current_message.binding_id == input.defaults.binding_id
                && current_message.domain_id == input.defaults.domain_id
                && current_message.endpoint_id == input.defaults.endpoint_id
                && current_message.endpoint_generation == input.defaults.endpoint_generation
                && current_message.gateway_id == input.defaults.gateway_id
                && current_message.gateway_generation == input.defaults.gateway_generation;
            if exact_recovery {
                let response = pb::TopologyDefaultsResponse {
                    defaults: Some(current_message),
                };
                self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
                    .await?;
                return Ok(response);
            }
            if Some(current.resource_version) != input.baseline_resource_version {
                return Err(RpcError::FailedPrecondition(
                    "topology defaults changed after planning".to_string(),
                ));
            }
        } else if input.baseline_resource_version.is_some() {
            return Err(RpcError::FailedPrecondition(
                "topology defaults were deleted after planning".to_string(),
            ));
        }

        fn optional(value: &str) -> Option<&str> {
            (!value.is_empty()).then_some(value)
        }
        let optional_generation = |value: i64| (value > 0).then_some(value);
        let defaults = self
            .db
            .set_stable_topology_defaults(
                if instance { "instance" } else { "organization" },
                input.org_id,
                &input.defaults.scope_key,
                optional(&input.defaults.binding_id),
                optional(&input.defaults.domain_id),
                optional(&input.defaults.endpoint_id),
                optional_generation(input.defaults.endpoint_generation),
                optional(&input.defaults.gateway_id),
                optional_generation(input.defaults.gateway_generation),
                input.baseline_resource_version,
            )
            .await
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))?;
        let response = pb::TopologyDefaultsResponse {
            defaults: Some(Self::stable_topology_defaults_message(defaults)),
        };
        self.complete_control_plan(&plan.plan_id, &req.idempotency_key, &response)
            .await?;
        Ok(response)
    }

    /// Applies an instance topology-default replacement plan.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, stale-plan, or persistence error.
    pub async fn apply_set_instance_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::ApplySetTopologyDefaultsRequest,
    ) -> Result<pb::TopologyDefaultsResponse, RpcError> {
        self.apply_set_topology_defaults(auth, req, true).await
    }

    /// Applies an organization topology-default replacement plan.
    ///
    /// # Errors
    ///
    /// Returns an authorization, confirmation, stale-plan, or persistence error.
    pub async fn apply_set_organization_topology_defaults(
        &self,
        auth: Option<&str>,
        req: pb::ApplySetTopologyDefaultsRequest,
    ) -> Result<pb::TopologyDefaultsResponse, RpcError> {
        self.apply_set_topology_defaults(auth, req, false).await
    }

    /// Resolves and authorizes a typed topology surface reference.
    async fn readable_topology_surface(
        &self,
        auth: Option<&str>,
        surface: Option<pb::SurfaceRef>,
    ) -> Result<crate::db::SurfaceTarget, RpcError> {
        match surface.and_then(|surface| surface.target) {
            Some(pb::surface_ref::Target::RegistrySlug(slug)) if !slug.is_empty() => {
                let registry = self.registry_or_not_found(&slug).await?;
                self.require_read(auth, &registry).await?;
                Ok(crate::db::SurfaceTarget::Registry(registry.id))
            }
            Some(pb::surface_ref::Target::CacheSlug(slug)) if !slug.is_empty() => {
                let cache = self
                    .db
                    .binary_cache_by_slug(&slug)
                    .await
                    .map_err(RpcError::internal)?
                    .ok_or_else(|| RpcError::not_found("cache"))?;
                self.require_cache_read(auth, &cache).await?;
                Ok(crate::db::SurfaceTarget::BinaryCache(cache.id))
            }
            Some(_) => Err(RpcError::invalid("surface slug must not be empty")),
            None => Err(RpcError::invalid(
                "surface must select exactly one registrySlug or cacheSlug",
            )),
        }
    }

    /// Resolves a typed surface and requires topology write authority.
    ///
    /// The IAM model does not yet have a dedicated `topology.manage` verb.
    /// Placement changes therefore temporarily use the stronger
    /// [`Permission::StorageManage`] capability on the owning organization;
    /// org-less resources require root [`Permission::IamAdmin`]. This mapping
    /// is intentionally centralized so a future dedicated verb is one change.
    async fn writable_topology_surface(
        &self,
        auth: Option<&str>,
        surface: Option<pb::SurfaceRef>,
    ) -> Result<(crate::db::SurfaceTarget, Option<i64>), RpcError> {
        let claims = self.require_claims(auth)?;
        let (target, org_id) = match surface.and_then(|surface| surface.target) {
            Some(pb::surface_ref::Target::RegistrySlug(slug)) if !slug.is_empty() => {
                let registry = self.registry_or_not_found(&slug).await?;
                (
                    crate::db::SurfaceTarget::Registry(registry.id),
                    registry.org_id,
                )
            }
            Some(pb::surface_ref::Target::CacheSlug(slug)) if !slug.is_empty() => {
                let cache = self
                    .db
                    .binary_cache_by_slug(&slug)
                    .await
                    .map_err(RpcError::internal)?
                    .ok_or_else(|| RpcError::not_found("cache"))?;
                if cache.deleted_at.is_some() {
                    return Err(RpcError::not_found("cache"));
                }
                (
                    crate::db::SurfaceTarget::BinaryCache(cache.id),
                    cache.org_id,
                )
            }
            Some(_) => return Err(RpcError::invalid("surface slug must not be empty")),
            None => {
                return Err(RpcError::invalid(
                    "surface must select exactly one registrySlug or cacheSlug",
                ));
            }
        };
        match org_id {
            Some(id) => {
                if !self
                    .db
                    .org_is_active(id)
                    .await
                    .map_err(RpcError::internal)?
                {
                    return Err(RpcError::not_found("surface"));
                }
                let org = self
                    .db
                    .org_by_id(id)
                    .await
                    .map_err(RpcError::internal)?
                    .ok_or_else(|| RpcError::not_found("org"))?;
                self.require_permission(
                    &claims,
                    Permission::StorageManage,
                    &Scope::parse(&org.stable_id),
                )
                .await?;
            }
            None => {
                self.require_permission(&claims, Permission::IamAdmin, &Scope::root())
                    .await?;
            }
        }
        Ok((target, org_id))
    }

    /// Resolves a binding by stable id in a surface's owning scope.
    async fn topology_binding_id(
        &self,
        org_id: Option<i64>,
        stable_id: &str,
    ) -> Result<i64, RpcError> {
        if stable_id.is_empty() {
            return Err(RpcError::invalid("bindingId is required"));
        }
        let binding = match org_id {
            Some(id) => self
                .db
                .list_bindings(id)
                .await
                .map_err(RpcError::internal)?
                .into_iter()
                .find(|binding| binding.stable_id == stable_id),
            None => None,
        };
        if let Some(binding) = binding {
            return Ok(binding.id);
        }
        self.db
            .instance_default_binding()
            .await
            .map_err(RpcError::internal)?
            .filter(|binding| binding.stable_id == stable_id)
            .map(|binding| binding.id)
            .ok_or_else(|| RpcError::not_found("binding"))
    }

    /// Returns the canonical authorization and plan scope for one typed surface.
    fn topology_scope(registry_id: Option<i64>, cache_id: Option<i64>) -> String {
        match (registry_id, cache_id) {
            (Some(id), None) => format!("topology:registry:{id}"),
            (None, Some(id)) => format!("topology:cache:{id}"),
            _ => "topology:invalid".to_string(),
        }
    }

    /// Validates the complete desired shape of a placement.
    fn validate_placement_shape(
        kind: &str,
        desired_state: &str,
        desired_read_enabled: Option<bool>,
        read_order: Option<i64>,
        hash_range: Option<&pb::HashRangeV1>,
    ) -> Result<(), RpcError> {
        let desired_read_enabled =
            Self::required_placement_field(desired_read_enabled, "desiredReadEnabled")?;
        let _ = Self::required_placement_field(read_order, "readOrder")?;
        if !matches!(kind, "complete" | "shard" | "archive") {
            return Err(RpcError::invalid(
                "kind must be complete, shard, or archive",
            ));
        }
        if !matches!(desired_state, "active" | "offline") {
            return Err(RpcError::invalid(
                "desiredState must be active or offline at creation",
            ));
        }
        if kind == "archive" && desired_read_enabled {
            return Err(RpcError::invalid(
                "archive placements cannot be read-enabled",
            ));
        }
        match (kind, hash_range) {
            ("shard", Some(range)) if range.start < range.end && range.end <= 65_536 => Ok(()),
            ("shard", _) => Err(RpcError::invalid(
                "shard placements require a non-empty 16-bit hashRange",
            )),
            (_, None) => Ok(()),
            (_, Some(_)) => Err(RpcError::invalid(
                "hashRange is valid only for shard placements",
            )),
        }
    }

    /// Checks whether a prior successful create is the exact reviewed outcome.
    fn placement_matches_create(
        placement: &crate::db::SurfacePlacementRecord,
        input: &PlacementCreatePlanInput,
    ) -> bool {
        let range = input
            .request
            .hash_range
            .as_ref()
            .map(|range| (i64::from(range.start), i64::from(range.end)));
        placement.binding_id == input.binding_db_id
            && placement.prefix == input.request.prefix
            && placement.kind == input.request.kind
            && placement.desired_state == input.request.desired_state
            && placement.desired_read_enabled == input.request.desired_read_enabled.unwrap_or(false)
            && placement.read_order == input.request.read_order.unwrap_or_default()
            && placement.requires_conditional_writes == input.request.requires_conditional_writes
            && (placement.hash_range_start.zip(placement.hash_range_end)) == range
    }

    /// Finds one placement by its stable name within an already-resolved surface.
    async fn topology_placement(
        &self,
        surface: crate::db::SurfaceTarget,
        name: &str,
    ) -> Result<crate::db::SurfacePlacementRecord, RpcError> {
        if name.is_empty() {
            return Err(RpcError::invalid("placement name must not be empty"));
        }
        self.db
            .list_surface_placements(surface)
            .await
            .map_err(RpcError::internal)?
            .into_iter()
            .find(|placement| placement.name == name)
            .ok_or_else(|| RpcError::not_found("placement"))
    }

    /// Resolves the single fully reconciled placement that may receive writes.
    async fn effective_surface_writer(
        &self,
        surface: SurfaceTarget,
    ) -> Result<crate::db::SurfacePlacementRecord, RpcError> {
        self.db
            .reconciled_surface_writer(surface)
            .await
            .map_err(|error| RpcError::FailedPrecondition(format!("{error:#}")))
    }

    /// Resolves the immutable binding revision and credential generation a
    /// caller must pin when creating an observing write ticket.
    async fn placement_write_snapshot(
        &self,
        placement: &crate::db::SurfacePlacementRecord,
    ) -> Result<(i64, i64), RpcError> {
        let binding_revision = placement
            .authority_observed_binding_write_revision
            .ok_or_else(|| RpcError::FailedPrecondition("writer has no binding revision".into()))?;
        let revision = self
            .db
            .binding_write_revision(placement.binding_id, binding_revision)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::FailedPrecondition("writer revision disappeared".into()))?;
        Ok((binding_revision, revision.write_credential_generation))
    }

    /// Builds a reusable reader whose every object access is placement-planned.
    fn topology_surface_fetcher(&self, surface: SurfaceTarget) -> Box<dyn SurfaceFetch> {
        Box::new(crate::placement_read::TopologySurfaceFetch::new(
            Arc::clone(&self.db),
            Arc::clone(&self.surface),
            surface,
        ))
    }

    /// Parses and verifies an opaque placement resource version.
    fn expected_placement_version(
        expected: &str,
        placement: &crate::db::SurfacePlacementRecord,
    ) -> Result<i64, RpcError> {
        let version = expected.parse::<i64>().map_err(|_| {
            RpcError::invalid("expectedResourceVersion must be a positive opaque version")
        })?;
        if version <= 0 {
            return Err(RpcError::invalid(
                "expectedResourceVersion must be a positive opaque version",
            ));
        }
        if version != placement.resource_version {
            return Err(RpcError::FailedPrecondition(
                "placement resource version is stale".to_string(),
            ));
        }
        Ok(version)
    }

    /// Requires an explicitly present proto3 optional placement field.
    fn required_placement_field<T>(value: Option<T>, name: &str) -> Result<T, RpcError> {
        value.ok_or_else(|| RpcError::invalid(format!("{name} must be specified")))
    }

    /// Returns the database-id tuple for a typed surface.
    fn topology_surface_ids(surface: SurfaceTarget) -> (Option<i64>, Option<i64>) {
        match surface {
            SurfaceTarget::Registry(id) => (Some(id), None),
            SurfaceTarget::BinaryCache(id) => (None, Some(id)),
        }
    }

    /// Maps typed placement-create failures without parsing SQL-driver text.
    fn placement_create_error(error: anyhow::Error) -> RpcError {
        let Some(failure) = crate::db::surface_placement_create_failure(&error) else {
            return RpcError::internal(error);
        };
        match failure.kind() {
            crate::db::SurfacePlacementCreateFailureKind::InvalidArgument => {
                RpcError::invalid(failure.public_message())
            }
            crate::db::SurfacePlacementCreateFailureKind::AlreadyExists => {
                RpcError::AlreadyExists(failure.public_message().to_string())
            }
            crate::db::SurfacePlacementCreateFailureKind::Conflict => {
                RpcError::FailedPrecondition(failure.public_message().to_string())
            }
        }
    }

    /// Maps typed authority preconditions while preserving infrastructure failures.
    fn authority_mutation_error(error: anyhow::Error) -> RpcError {
        match crate::db::surface_write_authority_mutation_failure(&error) {
            Some(failure) => RpcError::FailedPrecondition(failure.public_message().to_string()),
            None => RpcError::internal(error),
        }
    }

    /// Returns a stable route-pin precondition without backend constraint text.
    fn placement_route_pin_error(
        blockers: crate::db::SurfacePlacementBlockers,
    ) -> Option<RpcError> {
        if blockers.direct_route {
            Some(RpcError::FailedPrecondition(
                "placement is pinned by a direct route".to_string(),
            ))
        } else if blockers.routed_policy {
            Some(RpcError::FailedPrecondition(
                "placement is pinned by a delivery-route placement policy".to_string(),
            ))
        } else {
            None
        }
    }

    /// Returns the first stable metadata-deletion precondition.
    fn placement_delete_blocker_error(
        blockers: crate::db::SurfacePlacementBlockers,
    ) -> Option<RpcError> {
        if blockers.direct_route {
            Some(RpcError::FailedPrecondition(
                "placement is referenced by a direct route".to_string(),
            ))
        } else if blockers.policy_member {
            Some(RpcError::FailedPrecondition(
                "placement is referenced by a placement policy".to_string(),
            ))
        } else if blockers.object_presence {
            Some(RpcError::FailedPrecondition(
                "placement has object-presence inventory".to_string(),
            ))
        } else if blockers.publication {
            Some(RpcError::FailedPrecondition(
                "placement has registry-publication state".to_string(),
            ))
        } else if blockers.deletion_job {
            Some(RpcError::FailedPrecondition(
                "placement has object-deletion jobs".to_string(),
            ))
        } else if blockers.topology_operation {
            Some(RpcError::FailedPrecondition(
                "placement has topology operations".to_string(),
            ))
        } else {
            None
        }
    }

    /// Builds the public placement message without exposing database identity
    /// or backend-specific shard configuration.
    async fn placement_message(
        &self,
        placement: crate::db::SurfacePlacementRecord,
    ) -> Result<pb::Placement, RpcError> {
        let binding = self
            .db
            .binding(placement.binding_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| {
                RpcError::internal(anyhow::anyhow!(
                    "placement '{}' references missing binding {}",
                    placement.name,
                    placement.binding_id
                ))
            })?;
        let hash_range = match (placement.hash_range_start, placement.hash_range_end) {
            (Some(start), Some(end)) => Some(pb::HashRangeV1 {
                start: u32::try_from(start).map_err(RpcError::internal)?,
                end: u32::try_from(end).map_err(RpcError::internal)?,
            }),
            (None, None) => None,
            _ => {
                return Err(RpcError::internal(anyhow::anyhow!(
                    "placement '{}' has an incomplete hash range",
                    placement.name
                )));
            }
        };
        let desired_writer = placement.authority_desired_placement_id == Some(placement.id);
        let observed_writer = placement.authority_observed_placement_id == Some(placement.id);
        Ok(pb::Placement {
            name: placement.name,
            binding_name: binding.name,
            prefix: placement.prefix,
            spec: Some(pb::PlacementSpec {
                kind: placement.kind,
                desired_state: placement.desired_state,
                desired_read_enabled: placement.desired_read_enabled,
                read_order: placement.read_order,
                write_spec_version: placement.write_spec_version,
                requires_conditional_writes: placement.requires_conditional_writes,
                hash_range,
            }),
            observation: Some(pb::PlacementObservation {
                state: placement.state,
                completeness: placement.completeness,
                observed_at: placement.observed_at.unwrap_or_default(),
                observation_version: placement
                    .observation_version
                    .map(|version| version.to_string())
                    .unwrap_or_default(),
                mutable_publication_id: placement.mutable_publication_id.unwrap_or_default(),
                pending_publication_id: placement
                    .watermark_pending_publication_id
                    .unwrap_or_default(),
                watermark_resource_version: placement
                    .watermark_resource_version
                    .map(|version| version.to_string())
                    .unwrap_or_default(),
            }),
            status: Some(pb::PlacementStatus {
                derived_role: placement.derived_role,
                desired_writer,
                observed_writer,
                promotion_pending: desired_writer
                    && placement.authority_desired_generation
                        != placement.authority_observed_generation,
                effective_read_enabled: placement.effective_read_enabled,
                effective_write_enabled: placement.effective_write_enabled,
            }),
            created_at: placement.created_at,
            updated_at: placement.updated_at,
            resource_version: placement.resource_version.to_string(),
        })
    }

    /// Builds the public desired/observed authority view using placement names.
    async fn write_authority_message(
        &self,
        authority: crate::db::SurfaceWriteAuthorityRecord,
    ) -> Result<pb::SurfaceWriteAuthority, RpcError> {
        let desired = self
            .db
            .surface_placement(authority.desired_placement_id)
            .await
            .map_err(RpcError::internal)?
            .ok_or_else(|| RpcError::internal(anyhow::anyhow!("desired writer is missing")))?;
        let observed_placement_name = match authority.observed_placement_id {
            Some(id) => {
                self.db
                    .surface_placement(id)
                    .await
                    .map_err(RpcError::internal)?
                    .ok_or_else(|| {
                        RpcError::internal(anyhow::anyhow!("observed writer is missing"))
                    })?
                    .name
            }
            None => String::new(),
        };
        Ok(pb::SurfaceWriteAuthority {
            mode: authority.mode,
            desired_placement_name: desired.name,
            observed_placement_name,
            desired_write_spec_version: authority.desired_write_spec_version,
            observed_write_spec_version: authority.observed_write_spec_version.unwrap_or_default(),
            desired_binding_write_revision: authority.desired_binding_write_revision,
            observed_binding_write_revision: authority
                .observed_binding_write_revision
                .unwrap_or_default(),
            desired_generation: authority.desired_generation,
            observed_generation: authority.observed_generation.unwrap_or_default(),
            reconciliation_state: authority.reconciliation_state,
            reconciliation_error: authority.reconciliation_error.unwrap_or_default(),
            resource_version: authority.resource_version.to_string(),
            incarnation_id: authority.incarnation_id,
        })
    }

    fn policy_retry_name(value: i32) -> Result<String, RpcError> {
        let condition = pb::PolicyRetryCondition::try_from(value)
            .map_err(|_| RpcError::invalid("unknown placement-policy retry condition"))?;
        match condition {
            pb::PolicyRetryCondition::Unspecified => Err(RpcError::invalid(
                "retryOn cannot contain the unspecified value",
            )),
            pb::PolicyRetryCondition::ConnectFailure => Ok("connect_failure".to_string()),
            pb::PolicyRetryCondition::TimeoutBeforeHeaders => {
                Ok("timeout_before_headers".to_string())
            }
            pb::PolicyRetryCondition::Origin429 => Ok("origin_429".to_string()),
            pb::PolicyRetryCondition::Origin502 => Ok("origin_502".to_string()),
            pb::PolicyRetryCondition::Origin503 => Ok("origin_503".to_string()),
            pb::PolicyRetryCondition::Origin504 => Ok("origin_504".to_string()),
            pb::PolicyRetryCondition::PresenceMismatch => Ok("presence_mismatch".to_string()),
            pb::PolicyRetryCondition::VerifiedCorruption => Ok("verified_corruption".to_string()),
        }
    }

    fn policy_retry_value(value: &str) -> Result<i32, RpcError> {
        let value = match value {
            "connect_failure" => pb::PolicyRetryCondition::ConnectFailure,
            "timeout_before_headers" => pb::PolicyRetryCondition::TimeoutBeforeHeaders,
            "origin_429" => pb::PolicyRetryCondition::Origin429,
            "origin_502" => pb::PolicyRetryCondition::Origin502,
            "origin_503" => pb::PolicyRetryCondition::Origin503,
            "origin_504" => pb::PolicyRetryCondition::Origin504,
            "presence_mismatch" => pb::PolicyRetryCondition::PresenceMismatch,
            "verified_corruption" => pb::PolicyRetryCondition::VerifiedCorruption,
            _ => {
                return Err(RpcError::internal(anyhow::anyhow!(
                    "persisted placement-policy retry condition is invalid"
                )));
            }
        };
        Ok(value as i32)
    }

    async fn placement_policy_message(
        &self,
        identity: crate::db::PlacementPolicyIdentityRecord,
    ) -> Result<pb::PlacementPolicy, RpcError> {
        let current = match identity.current_revision_id.as_deref() {
            Some(id) => self
                .db
                .placement_policy_revision(id)
                .await
                .map_err(RpcError::internal)?,
            None => None,
        };
        Ok(pb::PlacementPolicy {
            stable_id: identity.id,
            surface: Some(self.route_surface_message(identity.surface).await?),
            name: identity.name,
            kind: current
                .as_ref()
                .map(|revision| revision.spec.kind.clone())
                .unwrap_or_default(),
            current_revision: current
                .as_ref()
                .map(|revision| revision.revision)
                .unwrap_or_default(),
            current_content_digest: current
                .and_then(|revision| revision.content_digest)
                .unwrap_or_default(),
            resource_version: identity.resource_version.to_string(),
            created_at: identity.created_at,
            updated_at: identity.updated_at,
        })
    }

    async fn placement_policy_revision_message(
        &self,
        revision: crate::db::PlacementPolicyRevisionRecord,
    ) -> Result<pb::PlacementPolicyRevision, RpcError> {
        let (groups, members) = self
            .db
            .placement_policy_revision_shape(&revision.id)
            .await
            .map_err(RpcError::internal)?;
        let mut projected = Vec::with_capacity(groups.len());
        for group in &groups {
            let mut placement_names = Vec::new();
            for member in members
                .iter()
                .filter(|member| member.group_id == group.group_id)
            {
                placement_names.push(
                    self.db
                        .surface_placement(member.placement_id)
                        .await
                        .map_err(RpcError::internal)?
                        .ok_or_else(|| {
                            RpcError::internal(anyhow::anyhow!(
                                "policy revision member placement is missing"
                            ))
                        })?
                        .name,
                );
            }
            let hash_range = if let (Some(start), Some(end)) = (group.range_start, group.range_end)
            {
                Some(pb::HashRangeV1 {
                    start: u32::try_from(start).map_err(|_| {
                        RpcError::internal(anyhow::anyhow!(
                            "persisted placement-policy range start is outside u32"
                        ))
                    })?,
                    end: u32::try_from(end).map_err(|_| {
                        RpcError::internal(anyhow::anyhow!(
                            "persisted placement-policy range end is outside u32"
                        ))
                    })?,
                })
            } else {
                None
            };
            projected.push(pb::PlacementPolicyReplicaGroup {
                placement_names,
                access_class: match group.purpose.as_str() {
                    "local" => pb::AccessClass::Local as i32,
                    "remote" => pb::AccessClass::Remote as i32,
                    _ => pb::AccessClass::Unspecified as i32,
                },
                hash_range,
            });
        }
        let selector = match revision.spec.kind.as_str() {
            "ordered_failover" => pb::placement_policy_revision_spec::Selector::OrderedFailover(
                pb::OrderedFailoverPlacementPolicy {
                    replica_groups: projected,
                },
            ),
            "local_then_remote" => pb::placement_policy_revision_spec::Selector::LocalThenRemote(
                pb::LocalThenRemotePlacementPolicy {
                    replica_groups: projected,
                    local_boundary: Some(pb::NetworkPolicyRevisionRef {
                        boundary_id: revision.spec.local_boundary_id.clone().unwrap_or_default(),
                        revision: revision.spec.local_boundary_revision.unwrap_or_default(),
                    }),
                    allow_remote_fallback: revision.spec.allow_remote_fallback.unwrap_or(false),
                },
            ),
            "hash_partition" => {
                let mut ranges = Vec::new();
                let mut complete_fallback_placements = Vec::new();
                for (record, message) in groups.iter().zip(projected) {
                    if record.purpose == "complete_fallback" {
                        complete_fallback_placements.extend(message.placement_names);
                    } else {
                        ranges.push(message);
                    }
                }
                pb::placement_policy_revision_spec::Selector::HashPartition(
                    pb::HashPartitionPlacementPolicy {
                        ranges,
                        complete_fallback_placements,
                    },
                )
            }
            _ => {
                return Err(RpcError::internal(anyhow::anyhow!(
                    "persisted placement policy kind is invalid"
                )));
            }
        };
        let retry_on = revision
            .spec
            .retry_on
            .iter()
            .map(|condition| Self::policy_retry_value(condition))
            .collect::<Result<Vec<_>, _>>()?;
        Ok(pb::PlacementPolicyRevision {
            policy_id: revision.policy_id,
            revision: revision.revision,
            spec: Some(pb::PlacementPolicyRevisionSpec {
                selector: Some(selector),
                failure_contract: Some(pb::PolicyFailureContract { retry_on }),
            }),
            content_digest: revision.content_digest.unwrap_or_default(),
            created_by: revision.created_by,
            created_at: revision.created_at,
        })
    }

    async fn normalize_placement_policy_request(
        &self,
        surface: SurfaceTarget,
        request: pb::PlanPlacementPolicyMutationRequest,
        owner_scope_key: String,
        baseline_policy_resource_version: Option<i64>,
    ) -> Result<PlacementPolicyMutationPlanInput, RpcError> {
        let desired = request
            .desired
            .as_ref()
            .ok_or_else(|| RpcError::invalid("desired policy revision is required"))?;
        let failure_contract = desired
            .failure_contract
            .as_ref()
            .ok_or_else(|| RpcError::invalid("failureContract is required"))?;
        let mut retry_names = Vec::with_capacity(failure_contract.retry_on.len());
        let mut unique_retry = BTreeSet::new();
        for condition in &failure_contract.retry_on {
            let name = Self::policy_retry_name(*condition)?;
            if !unique_retry.insert(name.clone()) {
                return Err(RpcError::invalid("retryOn cannot contain duplicates"));
            }
            retry_names.push(name);
        }
        let mut normalized_groups: Vec<(String, Option<(i64, i64)>, Vec<String>)> = Vec::new();
        let (kind, boundary, allow_remote_fallback) = match desired.selector.as_ref() {
            Some(pb::placement_policy_revision_spec::Selector::OrderedFailover(policy)) => {
                if policy.replica_groups.is_empty() {
                    return Err(RpcError::invalid(
                        "ordered failover requires at least one replica group",
                    ));
                }
                for group in &policy.replica_groups {
                    if group.access_class != pb::AccessClass::Unspecified as i32
                        || group.hash_range.is_some()
                    {
                        return Err(RpcError::invalid(
                            "ordered-failover groups forbid accessClass and hashRange",
                        ));
                    }
                    normalized_groups.push((
                        "ordered".to_string(),
                        None,
                        group.placement_names.clone(),
                    ));
                }
                ("ordered_failover".to_string(), None, None)
            }
            Some(pb::placement_policy_revision_spec::Selector::LocalThenRemote(policy)) => {
                if policy.replica_groups.is_empty() {
                    return Err(RpcError::invalid(
                        "local-then-remote requires at least one replica group",
                    ));
                }
                let boundary = policy.local_boundary.clone().ok_or_else(|| {
                    RpcError::invalid("localBoundary is required for local-then-remote")
                })?;
                if boundary.boundary_id.is_empty() || boundary.revision <= 0 {
                    return Err(RpcError::invalid(
                        "localBoundary must identify a positive exact revision",
                    ));
                }
                for group in &policy.replica_groups {
                    if group.hash_range.is_some() {
                        return Err(RpcError::invalid(
                            "local-then-remote groups forbid hashRange",
                        ));
                    }
                    let purpose = match pb::AccessClass::try_from(group.access_class) {
                        Ok(pb::AccessClass::Local) => "local",
                        Ok(pb::AccessClass::Remote) => "remote",
                        _ => {
                            return Err(RpcError::invalid(
                                "local-then-remote groups require local or remote accessClass",
                            ));
                        }
                    };
                    normalized_groups.push((
                        purpose.to_string(),
                        None,
                        group.placement_names.clone(),
                    ));
                }
                if normalized_groups.iter().all(|group| group.0 != "local")
                    || (policy.allow_remote_fallback
                        && normalized_groups.iter().all(|group| group.0 != "remote"))
                {
                    return Err(RpcError::invalid(
                        "local-then-remote group coverage is incomplete",
                    ));
                }
                (
                    "local_then_remote".to_string(),
                    Some(boundary),
                    Some(policy.allow_remote_fallback),
                )
            }
            Some(pb::placement_policy_revision_spec::Selector::HashPartition(policy)) => {
                if policy.ranges.is_empty() {
                    return Err(RpcError::invalid(
                        "hash partition requires at least one range",
                    ));
                }
                for group in &policy.ranges {
                    if group.access_class != pb::AccessClass::Unspecified as i32 {
                        return Err(RpcError::invalid(
                            "hash-partition ranges forbid accessClass",
                        ));
                    }
                    let range = group.hash_range.as_ref().ok_or_else(|| {
                        RpcError::invalid("hash-partition groups require hashRange")
                    })?;
                    if range.start >= range.end || range.end > 65_536 {
                        return Err(RpcError::invalid(
                            "hashRange must be a non-empty range within 0..65536",
                        ));
                    }
                    normalized_groups.push((
                        "hash_range".to_string(),
                        Some((i64::from(range.start), i64::from(range.end))),
                        group.placement_names.clone(),
                    ));
                }
                if !policy.complete_fallback_placements.is_empty() {
                    normalized_groups.push((
                        "complete_fallback".to_string(),
                        None,
                        policy.complete_fallback_placements.clone(),
                    ));
                }
                ("hash_partition".to_string(), None, None)
            }
            None => return Err(RpcError::invalid("policy selector is required")),
        };
        let mut groups = Vec::with_capacity(normalized_groups.len());
        let mut all_members = BTreeSet::new();
        for (index, (purpose, range, names)) in normalized_groups.into_iter().enumerate() {
            if names.is_empty() {
                return Err(RpcError::invalid(
                    "every placement-policy group requires at least one member",
                ));
            }
            let mut members = Vec::with_capacity(names.len());
            let mut local_members = BTreeSet::new();
            for name in names {
                if !local_members.insert(name.clone()) || !all_members.insert(name.clone()) {
                    return Err(RpcError::invalid(
                        "a placement may occur only once in a policy revision",
                    ));
                }
                let placement = self.topology_placement(surface, &name).await?;
                let expected_kind = if purpose == "hash_range" {
                    "shard"
                } else {
                    "complete"
                };
                if placement.kind != expected_kind {
                    return Err(RpcError::invalid(format!(
                        "placement '{name}' must be {expected_kind} for this group"
                    )));
                }
                if purpose == "hash_range"
                    && placement.hash_range_start.zip(placement.hash_range_end) != range
                {
                    return Err(RpcError::invalid(format!(
                        "shard placement '{name}' does not match its policy range"
                    )));
                }
                members.push(PlacementPolicyMemberPlanSeal {
                    name,
                    placement_id: placement.id,
                    resource_version: placement.resource_version,
                    kind: placement.kind,
                });
            }
            groups.push(PlacementPolicyGroupPlanSeal {
                group_id: format!("group:{index}"),
                purpose,
                range_start: range.map(|value| value.0),
                range_end: range.map(|value| value.1),
                members,
            });
        }
        let (local_boundary_id, local_boundary_revision, local_boundary_content_digest) =
            if let Some(boundary) = boundary {
                let record = self
                    .db
                    .network_policy_revision(&boundary.boundary_id, boundary.revision)
                    .await
                    .map_err(RpcError::internal)?
                    .ok_or_else(|| RpcError::not_found("network policy revision"))?;
                if record.lifecycle_state != "active" || record.observation_state != "verified" {
                    return Err(RpcError::FailedPrecondition(
                        "local boundary revision must be active and verified".to_string(),
                    ));
                }
                (
                    Some(record.boundary_id),
                    Some(record.revision),
                    Some(record.content_digest),
                )
            } else {
                (None, None, None)
            };
        let (registry_id, cache_id) = Self::topology_surface_ids(surface);
        Ok(PlacementPolicyMutationPlanInput {
            request,
            registry_id,
            cache_id,
            owner_scope_key,
            baseline_policy_resource_version,
            kind,
            local_boundary_id,
            local_boundary_revision,
            local_boundary_content_digest,
            allow_remote_fallback,
            retry_on: retry_names,
            groups,
        })
    }

    /// Returns the complete current topology projection for one surface.
    pub async fn get_surface_topology(
        &self,
        auth: Option<&str>,
        req: pb::GetSurfaceTopologyRequest,
    ) -> Result<pb::GetSurfaceTopologyResponse, RpcError> {
        let surface = self
            .readable_topology_surface(auth, req.surface.clone())
            .await?;
        let owner_scope_key = self.route_surface_owner_scope(surface).await?;
        self.require_delivery_scope(auth, &owner_scope_key, Permission::RouteRead)
            .await?;
        let placement_records = self
            .db
            .list_surface_placements(surface)
            .await
            .map_err(RpcError::internal)?;
        let mut placements = Vec::with_capacity(placement_records.len());
        for record in placement_records {
            placements.push(self.placement_message(record).await?);
        }
        let route_records = self
            .db
            .list_routes(surface)
            .await
            .map_err(RpcError::internal)?;
        let mut routes = Vec::with_capacity(route_records.len());
        for record in &route_records {
            routes.push(self.route_message(record.clone()).await?);
        }
        let mut route_advertisements = Vec::new();
        let mut canonical_endpoint_ids = BTreeSet::new();
        for audience in ["git", "nix_cache", "web"] {
            if let Some(record) = self
                .db
                .route_advertisement(surface, audience)
                .await
                .map_err(RpcError::internal)?
            {
                route_advertisements.push(pb::RouteAdvertisement {
                    surface: Some(self.route_surface_message(surface).await?),
                    audience: record.audience,
                    route_id: record.route_id.clone(),
                    resource_version: record.resource_version.to_string(),
                });
                if let Some(route) = route_records
                    .iter()
                    .find(|route| route.id == record.route_id)
                {
                    canonical_endpoint_ids.insert(route.endpoint_id.clone());
                }
            }
        }
        let write_authority = self
            .db
            .surface_write_authority(surface)
            .await
            .map_err(RpcError::internal)?;
        let policy_records = self
            .db
            .list_placement_policy_identities(surface)
            .await
            .map_err(RpcError::internal)?;
        let mut placement_policies = Vec::with_capacity(policy_records.len());
        for record in policy_records {
            placement_policies.push(self.placement_policy_message(record).await?);
        }
        let equivalence_records = self
            .db
            .list_placement_equivalences(surface)
            .await
            .map_err(RpcError::internal)?;
        let mut placement_equivalences = Vec::with_capacity(equivalence_records.len());
        for record in equivalence_records {
            placement_equivalences.push(self.placement_equivalence_message(record).await?);
        }
        let mut canonical_endpoints = Vec::with_capacity(canonical_endpoint_ids.len());
        for endpoint_id in canonical_endpoint_ids {
            let endpoint = self
                .db
                .endpoint(&endpoint_id)
                .await
                .map_err(RpcError::internal)?
                .ok_or_else(|| {
                    RpcError::internal(anyhow::anyhow!("route advertisement endpoint is missing"))
                })?;
            canonical_endpoints.push(self.endpoint_message(endpoint).await?);
        }
        let active_operations = self
            .db
            .list_active_surface_operations(surface)
            .await
            .map_err(RpcError::internal)?
            .into_iter()
            .map(|operation| pb::OperationRef {
                operation_id: operation.operation_id,
                kind: operation.operation_kind,
                state: operation.state,
                created_at: operation.created_at,
            })
            .collect();
        Ok(pb::GetSurfaceTopologyResponse {
            surface: Some(self.route_surface_message(surface).await?),
            placements,
            routes,
            route_advertisements,
            write_authority: match write_authority {
                Some(authority) => Some(self.write_authority_message(authority).await?),
                None => None,
            },
            placement_policies,
            placement_equivalences,
            canonical_endpoints,
            active_operations,
        })
    }

    /// Explains route selection for one surface URL and machine path.
    pub async fn explain_surface_request(
        &self,
        auth: Option<&str>,
        req: pb::ExplainSurfaceRequestRequest,
    ) -> Result<pb::ExplainSurfaceRequestResponse, RpcError> {
        let surface = self.readable_topology_surface(auth, req.surface).await?;
        let owner_scope_key = self.route_surface_owner_scope(surface).await?;
        self.require_delivery_scope(auth, &owner_scope_key, Permission::RouteRead)
            .await?;
        let parsed = url::Url::parse(&req.url)
            .map_err(|error| RpcError::invalid(format!("url: {error}")))?;
        if !matches!(parsed.scheme(), "http" | "https")
            || parsed.host_str().is_none()
            || parsed.username() != ""
            || parsed.password().is_some()
        {
            return Err(RpcError::invalid(
                "url must be an absolute HTTP(S) URL without userinfo",
            ));
        }
        let machine_path = if req.machine_path.is_empty() {
            parsed.path().to_string()
        } else {
            req.machine_path.clone()
        };
        if !machine_path.starts_with('/')
            || machine_path
                .split('/')
                .any(|segment| matches!(segment, "." | ".."))
            || machine_path.contains('?')
            || machine_path.contains('#')
        {
            return Err(RpcError::invalid(
                "machinePath must be an absolute normalized path",
            ));
        }
        let origin = parsed.origin().ascii_serialization();
        let mut candidates = Vec::new();
        let mut rejection_reasons = Vec::new();
        for route in self
            .db
            .list_routes(surface)
            .await
            .map_err(RpcError::internal)?
        {
            let snapshot = self
                .db
                .route_snapshot(&route.id)
                .await
                .map_err(RpcError::internal)?
                .ok_or_else(|| RpcError::internal(anyhow::anyhow!("route snapshot is missing")))?;
            let route_url = url::Url::parse(&snapshot.canonical_url).map_err(RpcError::internal)?;
            let route_origin = route_url.origin().ascii_serialization();
            let path_matches = snapshot.spec.base_path.is_empty()
                || machine_path == snapshot.spec.base_path
                || machine_path
                    .strip_prefix(&snapshot.spec.base_path)
                    .is_some_and(|suffix| suffix.starts_with('/'));
            let capability = match req.access_class.as_str() {
                "git" => snapshot.spec.serves_git,
                "nix_cache" => snapshot.spec.serves_cache,
                "web" => snapshot.spec.serves_web,
                _ => {
                    return Err(RpcError::invalid(
                        "accessClass must be git, nix_cache, or web",
                    ));
                }
            };
            if route.enabled
                && snapshot.observation_state == "healthy"
                && route_origin == origin
                && path_matches
                && capability
            {
                candidates.push((snapshot.spec.base_path.len(), route.id));
            } else if route_origin == origin {
                rejection_reasons.push(format!(
                    "route '{}' rejected: enabled={}, healthy={}, path_match={}, capability={}",
                    route.id,
                    route.enabled,
                    snapshot.observation_state == "healthy",
                    path_matches,
                    capability
                ));
            }
        }
        candidates.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| left.1.cmp(&right.1)));
        let selected_route_id = candidates
            .first()
            .map(|candidate| candidate.1.clone())
            .unwrap_or_default();
        let mut decisions = vec![format!("normalized origin is {origin}")];
        if selected_route_id.is_empty() {
            rejection_reasons.push("no healthy enabled route matched the request".to_string());
        } else {
            decisions.push(format!(
                "selected longest matching base path on route '{selected_route_id}'"
            ));
        }
        Ok(pb::ExplainSurfaceRequestResponse {
            normalized_url: format!("{origin}{machine_path}"),
            selected_route_id,
            decisions,
            rejection_reasons,
        })
    }

    /// `TopologyService.ListPlacements` — lists physical placements by stable name.
    ///
    /// Registry visibility and cache visibility use their existing read gates;
    /// private surfaces therefore require the same bearer authority as their
    /// other public read APIs.
    ///
    /// # Errors
    ///
    /// Returns [`RpcError::InvalidArgument`] for a missing surface or malformed
    /// page token, the surface's usual authentication/authorization errors,
    /// [`RpcError::NotFound`] for an unknown surface, and
    /// [`RpcError::Internal`] on database failure.
    pub async fn list_placements(
        &self,
        auth: Option<&str>,
        req: pb::ListPlacementsRequest,
    ) -> Result<pb::ListPlacementsResponse, RpcError> {
        let surface = self.readable_topology_surface(auth, req.surface).await?;
        let records = self
            .db
            .list_surface_placements(surface)
            .await
            .map_err(RpcError::internal)?;
        let mut placements = Vec::with_capacity(records.len());
        for record in records {
            placements.push(self.placement_message(record).await?);
        }
        let (placements, next_page_token) = paginate(placements, req.page_size, &req.page_token)?;
        Ok(pb::ListPlacementsResponse {
            placements,
            next_page_token,
        })
    }

    /// `TopologyService.GetPlacement` — reads one placement by surface-local name.
    ///
    /// # Errors
    ///
    /// Returns [`RpcError::InvalidArgument`] for a missing surface or empty
    /// placement name, the surface's usual authentication/authorization errors,
    /// [`RpcError::NotFound`] for an unknown surface or placement, and
    /// [`RpcError::Internal`] on database failure.
    pub async fn get_placement(
        &self,
        auth: Option<&str>,
        req: pb::GetPlacementRequest,
    ) -> Result<pb::GetPlacementResponse, RpcError> {
        if req.name.is_empty() {
            return Err(RpcError::invalid("placement name must not be empty"));
        }
        let surface = self.readable_topology_surface(auth, req.surface).await?;
        let placement = self
            .db
            .list_surface_placements(surface)
            .await
            .map_err(RpcError::internal)?
            .into_iter()
            .find(|placement| placement.name == req.name)
            .ok_or_else(|| RpcError::not_found("placement"))?;
        Ok(pb::GetPlacementResponse {
            placement: Some(self.placement_message(placement).await?),
        })
    }

